  "Makaleyi kaynak olarak ekle": "Artikel als Quelle hinzufügen",
  "Yüklediğiniz PDF projeye “tam metin okundu” erişim seviyesiyle bağlanır. Asistan doğrudan alıntıyı ve sayfa numarasını yalnızca böyle kaynaklardan yapabilir. DOI girerseniz künye otomatik doldurulur ve doğrulanır.": "Das hochgeladene PDF wird mit der Zugriffsstufe „Volltext gelesen“ mit dem Projekt verknüpft. Nur aus solchen Quellen kann der Assistent wörtlich zitieren und Seitenzahlen angeben. Wenn Sie eine DOI eingeben, wird die Literaturangabe automatisch ausgefüllt und verifiziert.",
  "DOI (önerilir)": "DOI (empfohlen)",
