  "Kayıp": "Fehlt",
  "16 veri tabanında, 250 milyondan fazla yayında eşzamanlı arama: OpenAlex, Crossref, PubMed/Europe PMC, arXiv, DOAJ, OpenAIRE, ERIC, DBLP, DataCite, PLOS, Zenodo, HAL, Open Library ve INSPIRE-HEP. Sonuçlar birleştirilir, yinelenen kayıtlar ayıklanır ve her kaynağın erişim seviyesi gösterilir.": "Gleichzeitige Suche in über 250 Millionen Publikationen aus 16 Datenbanken: OpenAlex, Crossref, PubMed/Europe PMC, arXiv, DOAJ, OpenAIRE, ERIC, DBLP, DataCite, PLOS, Zenodo, HAL, Open Library und INSPIRE-HEP. Die Ergebnisse werden zusammengeführt, Dubletten entfernt und für jede Quelle die Zugriffsstufe angezeigt.",
