  "Eklenecek proje": "Projekt, dem hinzugefügt wird",
  "Eklenen kaynaklar DOI/PMID/arXiv üzerinden otomatik doğrulanır ve eksik künye alanları kayıt otoritesinden tamamlanır.": "Hinzugefügte Quellen werden automatisch über DOI/PMID/arXiv verifiziert; fehlende Felder der Literaturangabe werden von der Registrierungsstelle ergänzt.",
