  "Araştırma yaklaşımı": "Forschungsansatz",
  "Yaklaşım, yol haritasındaki aşamaları değiştirir (ör. nitel çalışmalarda “Evren ve örneklem” yerine “Çalışma grubu”).": "Der Ansatz verändert die Phasen im Fahrplan (z. B. „Untersuchungsgruppe“ statt „Grundgesamtheit und Stichprobe“ bei qualitativen Studien).",
