  "ör. Kişilik özellikleri, ebeveyn tutumları ve ilişki odaklı obsesif kompulsif belirtiler arasındaki ilişkinin incelenmesi": "z. B. Untersuchung des Zusammenhangs zwischen Persönlichkeitsmerkmalen, elterlichen Erziehungseinstellungen und beziehungsbezogenen Zwangssymptomen",
  "Konu henüz net değilse boş bırakabilirsiniz. İlk aşamadaki asistan konuyu belirlemenize yardım eder.": "Sie können dieses Feld leer lassen, wenn das Thema noch nicht feststeht. Der Assistent der ersten Phase hilft Ihnen, es einzugrenzen.",
