  "Aşamaları sonradan ekleyebilir, silebilir ve sıralayabilirsiniz. Üniversite kılavuzu yüklerseniz yeni bir düzen önerilir.": "Sie können Phasen später hinzufügen, löschen und neu anordnen. Wenn Sie eine Richtlinie Ihrer Hochschule hochladen, wird eine neue Struktur vorgeschlagen.",
  "Çalışma türü": "Art der Arbeit",
  "Araştırma bilgileri": "Forschungsdetails",
  "Gerçek kaynaklarla çalışan akademik asistan": "Ein wissenschaftlicher Assistent, der mit echten Quellen arbeitet",
  "Akademik çalışmanızı": "Steuern Sie Ihre wissenschaftliche Arbeit",
  "ilk fikirden": "von der ersten Idee",
  "son kaynakçaya kadar yönetin.": "bis zum fertigen Literaturverzeichnis.",
  "Tez, makale ve araştırma önerinizi adım adım ilerleyen bir yol haritasıyla hazırlayın. Kaynaklar OpenAlex, Crossref ve PubMed gibi veri tabanlarından gelir ve doğrulanır. Atıflar seçtiğiniz stile göre kendiliğinden biçimlenir.": "Erstellen Sie Ihre Abschlussarbeit, Ihren Fachartikel und Ihr Forschungsexposé mit einem Schritt-für-Schritt-Fahrplan. Die Quellen stammen aus Datenbanken wie OpenAlex, Crossref und PubMed und werden verifiziert. Zitate werden automatisch im gewählten Stil formatiert.",
  "Çalışmaya başla": "Jetzt loslegen",
