  "Ebeveyn tutumları, bireyin yakın ilişkilerdeki bağlanma örüntülerini şekillendiren temel etkenler arasında yer almaktadır": "Elterliche Erziehungseinstellungen gehören zu den zentralen Faktoren, die die Bindungsmuster eines Menschen in engen Beziehungen prägen",
  "İlişki odaklı obsesif belirtiler ise partnere yönelik yineleyici şüphelerle karakterizedir": "Beziehungsbezogene Zwangssymptome sind durch wiederkehrende Zweifel am Partner gekennzeichnet",
