  "OpenAlex · Crossref · PubMed taranıyor…": "Durchsuche OpenAlex · Crossref · PubMed …",
  "Üç temel güç": "Drei zentrale Stärken",
  "Metin üretmekten öte:": "Mehr als Textgenerierung:",
  "yönlendirilen": "ein begleiteter",
  "bir akademik süreç": "wissenschaftlicher Prozess",
  "Altı adımda, kontrol hep sizde.": "Sechs Schritte, stets unter Ihrer Kontrolle.",
  "Erişebildiği kadarını kullanır, ne kadarını okuduğunu söyler.": "Sie nutzt, worauf sie zugreifen kann, und sagt Ihnen, wie viel sie gelesen hat.",
  "Her kaynağın yanında erişim seviyesi açıkça yazar:": "Jede Quelle zeigt ihre Zugriffsstufe deutlich an:",
  "yalnızca künye": "nur bibliografische Angaben",
  "özet okundu": "Abstract gelesen",
  "veya": "oder",
  "tam metin okundu": "Volltext gelesen",
  "Yapay zekâ, yalnızca özetini gördüğü bir makaleyi tam metnini okumuş gibi yorumlamaz. Doğrulanamayan kaynaklar ise kesin referans olarak gösterilmez.": "Die KI interpretiert einen Artikel, von dem sie nur das Abstract kennt, nicht so, als hätte sie den Volltext gelesen. Nicht verifizierbare Quellen werden nicht als gesicherte Belege dargestellt.",
  "Akademik dürüstlük, tasarımın merkezinde.": "Wissenschaftliche Integrität im Kern der Gestaltung.",
  "En çok tercih edilen": "Am beliebtesten",
  "/ay": "/Mon.",
  "{name} paketini seç": "{name} wählen",
  "Akademik süreç yönetimi": "Steuerung des wissenschaftlichen Prozesses",
  "Çalışma türünüze, seviyenize ve yönteminize göre oluşan yol haritası. Her aşamanın kendine özel bir asistanı ve kuralları var. Bölümler arasında geçerken proje hafızası korunur.": "Ein Fahrplan passend zu Art der Arbeit, Stufe und Methode. Jede Phase hat eigene Assistenten und Regeln. Das Projektgedächtnis bleibt beim Wechsel zwischen Abschnitten erhalten.",
  "Dinamik aşama yapısı": "Dynamische Phasenstruktur",
  "Üniversite kılavuzundan bölüm önerisi": "Abschnittsvorschläge aus der Richtlinie Ihrer Hochschule",
  "İlerleme takibi": "Fortschrittsverfolgung",
  "Gerçek bilimsel araştırma": "Echte wissenschaftliche Recherche",
  "OpenAlex, Crossref, PubMed, arXiv, DOAJ, ERIC ve diğer veri tabanlarında eşzamanlı tarama. DOI, PMID ve arXiv kimlikleri doğrulanır.": "Gleichzeitige Suche in OpenAlex, Crossref, PubMed, arXiv, DOAJ, ERIC und weiteren Datenbanken. DOI-, PMID- und arXiv-Kennungen werden verifiziert.",
  "Erişim seviyesi şeffaflığı": "Transparenz der Zugriffsstufen",
  "Açık erişimli tam metin analizi": "Analyse von Open-Access-Volltexten",
  "Yinelenen kayıt birleştirme": "Zusammenführung doppelter Einträge",
  "Akademik yazım otomasyonu": "Automatisierung des wissenschaftlichen Schreibens",
  "Atıflar metne yazı olarak değil, kaynağa bağlı canlı öğeler olarak eklenir. Stili değiştirdiğinizde bütün metin ve kaynakça yeni stile dönüşür.": "Zitate werden nicht als einfacher Text, sondern als mit der Quelle verknüpfte, lebendige Elemente eingefügt. Wenn Sie den Stil ändern, werden der gesamte Text und das Literaturverzeichnis in den neuen Stil umgestellt.",
  "Eksik künye ve tutarlılık uyarısı": "Warnungen bei unvollständigen Literaturangaben und Inkonsistenzen",
  "DOCX ve PDF çıktı": "Ausgabe als DOCX und PDF",
  "Çalışma türünü seçin": "Art der Arbeit wählen",
  "Tez, makale, derleme veya araştırma önerisi seçin. Platform akademik standartlara uygun bir yol haritası çıkarır.": "Wählen Sie Abschlussarbeit, Fachartikel, Review oder Forschungsexposé. Die Plattform erstellt einen Fahrplan, der akademischen Standards entspricht.",
  "Konunuzu tanımlayın": "Thema festlegen",
  "Asistan konunuzu analiz eder, kavramları ayrıştırır ve sizinle birlikte bir çalışma planı yapar.": "Der Assistent analysiert Ihr Thema, zerlegt die Begriffe und erstellt mit Ihnen einen Arbeitsplan.",
  "Literatürü tarayın": "Literatur recherchieren",
  "Gerçek veri tabanlarında arama yapılır. Hangi kaynakları kütüphanenize ekleyeceğinize siz karar verirsiniz.": "Es werden echte Datenbanken durchsucht. Sie entscheiden, welche Quellen in Ihre Bibliothek aufgenommen werden.",
  "Bölümleri geliştirin": "Abschnitte ausarbeiten",
  "Her bölümde yazın, yeniden yazdırın, genişletin. Her iddia bir kaynağa bağlanır, her sürüm geçmişte saklanır.": "Schreiben, überarbeiten und erweitern Sie jeden Abschnitt. Jede Aussage ist mit einer Quelle verknüpft, jede Version bleibt im Verlauf erhalten.",
  "Atıf tutarlılığı, eksik künye, bölümler arası uyum ve akademik dil kontrol edilir.": "Geprüft werden Zitatkonsistenz, unvollständige Literaturangaben, Kohärenz zwischen den Abschnitten und wissenschaftliche Sprache.",
  "Dışa aktarın": "Exportieren",
  "Word, PDF, Markdown veya TXT olarak indirin. İçindekiler, numaralandırma ve kaynakça hazır gelir.": "Download als Word, PDF, Markdown oder TXT. Inhaltsverzeichnis, Nummerierung und Literaturverzeichnis sind bereits enthalten.",
  "Künye": "Bibliografische Angaben",
  "Özet": "Abstract",
  "Kaynak, veri, istatistik ve bulgu üretilmez. Kaynakla desteklenemeyen kesin iddia yazılmaz; eksik konular için kaynak aranır.": "Es werden keine Quellen, Daten, Statistiken oder Ergebnisse erfunden. Gesicherte Aussagen, die sich nicht mit einer Quelle belegen lassen, werden nicht geschrieben; für fehlende Themen wird nach Quellen gesucht.",
  "Bulgular bölümü sizin analizinize dayanır. Yüklediğiniz veriler gerçek hesaplamayla özetlenir.": "Der Ergebnisteil beruht auf Ihrer eigenen Analyse. Hochgeladene Daten werden mit echten Berechnungen zusammengefasst.",
  "Çalışmalarınız yalnızca size görünür. Satır düzeyinde güvenlik, şifreli depolama ve tek tıkla veri silme.": "Ihre Arbeit ist nur für Sie sichtbar. Sicherheit auf Zeilenebene, verschlüsselte Speicherung und Löschen der Daten mit einem Klick.",
  "İntihal şeffaflığı": "Transparenz bei Plagiaten",
  "Lisanslı bir servis bağlanmadan intihal yüzdesi gösterilmez. Sahte oranlar üretilmez.": "Ohne angebundenen lizenzierten Dienst wird kein Plagiatsprozentsatz angezeigt. Es werden keine Schein-Werte erzeugt.",
  "Notlar": "Notizen",
  "Yorumunuz iletildi": "Ihr Kommentar wurde gesendet",
  "Yazar, ilgili bölümün yorumlarında görecek.": "Die Autorin bzw. der Autor sieht ihn in den Kommentaren des betreffenden Abschnitts.",
