  "Akademik çalışmanızı gerçek ve doğrulanabilir kaynaklarla, şeffaf erişim seviyeleriyle ve bilimsel standartlara uygun biçimde hazırlayın.": "Erstellen Sie Ihre wissenschaftliche Arbeit mit echten, überprüfbaren Quellen, transparenten Zugriffsstufen und im Einklang mit wissenschaftlichen Standards.",
