  "Geçiş cümleleri ekleyin.": "Ergänzen Sie Überleitungssätze.",
  "Her paragraf tek bir ana fikre hizmet etmelidir.": "Jeder Absatz sollte einem einzigen Kerngedanken dienen.",
  "Atıf ve kaynak kontrolü": "Prüfung von Zitaten und Quellen",
  "Metin içi atıfları kaynakça ile eşleştirmek, eksik ve doğrulanamayan kaynakları belirlemek.": "Zitate im Text mit dem Literaturverzeichnis abgleichen und fehlende sowie nicht verifizierbare Quellen ermitteln.",
  "Metindeki atıfları tarayın.": "Durchsuchen Sie die Zitate im Text.",
  "Kaynakları veri tabanlarında doğrulayın.": "Verifizieren Sie die Quellen in Datenbanken.",
  "Desteksiz iddialara kaynak önerin.": "Schlagen Sie Quellen für unbelegte Aussagen vor.",
  "Kaynak önerileri yalnızca gerçek veri tabanı sonuçlarından yapılır.": "Quellenvorschläge werden nur aus echten Datenbankergebnissen gemacht.",
  "Arama stratejisi": "Suchstrategie",
  "Araştırma sorusuna uygun anahtar kelimeleri, eş anlamlıları ve veri tabanlarını belirlemek.": "Suchbegriffe, Synonyme und Datenbanken passend zur Forschungsfrage festlegen.",
  "Temel kavramları ve eş anlamlılarını listeleyin.": "Listen Sie die zentralen Begriffe und ihre Synonyme auf.",
  "Türkçe ve İngilizce terimleri eşleştirin.": "Ordnen Sie Begriffe sprachübergreifend zu (z. B. Deutsch und Englisch).",
  "Yıl, dil ve yayın türü filtrelerini seçin.": "Wählen Sie Filter für Jahr, Sprache und Publikationstyp.",
  "Arama dizgileri kaydedilir; tarama tekrarlanabilir olmalıdır.": "Suchstrings werden gespeichert; die Suche muss replizierbar sein.",
  "Hangi dillerde ve hangi yıllar arasında kaynak arıyorsunuz?": "In welchen Sprachen und aus welchem Zeitraum suchen Sie Quellen?",
  "Kaynak tarama ve seçim": "Sichtung und Auswahl der Quellen",
  "Bulunan kaynakları alaka, kalite ve erişim düzeyine göre elemek ve kütüphaneye eklemek.": "Die gefundenen Quellen nach Relevanz, Qualität und Zugriffsstufe sichten und in die Bibliothek aufnehmen.",
