  "Artık bu kaynaktan sayfa numaralı atıf ve doğrulama yapılabilir.": "Für diese Quelle sind jetzt Zitate mit Seitenzahl und Verifizierung möglich.",
  "Asistan bölümün tamamına göre öneri verecek.": "Der Assistent macht Vorschläge auf Grundlage des gesamten Abschnitts.",
  "Asistanla uygula": "Mit Assistent umsetzen",
  "Atla": "Überspringen",
  "Atlandı": "Übersprungen",
  "Atıf doğrulama": "Zitatprüfung",
  "Aşağıdaki paragraftaki [KAYNAK GEREKLİ] işaretli iddialar için kaynak bul ve paragrafı düzelt. ⟦C1⟧ gibi işaretler mevcut atıflardır; yerlerini ve yazımını aynen koru.": "Suche Quellen für die mit [KAYNAK GEREKLİ] markierten Aussagen im folgenden Absatz und korrigiere den Absatz. Markierungen wie ⟦C1⟧ sind bestehende Zitate; behalte ihre Position und Schreibweise exakt bei.",
  "Bağlantı koptuğunda bu cihazda saklanan metin sunucuya kaydedildi.": "Text, der offline auf diesem Gerät gespeichert wurde, wurde auf dem Server gesichert.",
  "Başlayalım": "Los geht’s",
  "Belgeye tablo olarak ekle": "Als Tabelle ins Dokument einfügen",
  "Biçim ayarları kaydedildi": "Formateinstellungen gespeichert",
  "Biçim ve kapak ayarları": "Format- und Titelblatteinstellungen",
  "Bu ay {item} limitinizin %{pct} kadarını kullandınız": "Sie haben in diesem Monat {pct} % Ihres Limits für {item} verbraucht",
  "Bu bölüm için akademik standartlara uygun 3–6 alt başlık öner. Mevcut alt başlıkları tekrar etme. Yalnızca bir :::taslak bloğu içinde her satıra bir alt başlık yaz; numara veya açıklama ekleme.": "Schlage für diesen Abschnitt 3–6 Unterüberschriften vor, die wissenschaftlichen Standards entsprechen. Wiederhole keine vorhandenen Unterüberschriften. Schreibe in einem einzigen :::taslak-Block nur eine Unterüberschrift pro Zeile, ohne Nummern oder Erläuterungen.",
  "Bu bölümün yalnızca “{h}” alt başlığını yaz. Taslağı “## {h}” başlığıyla başlat; diğer alt başlıkları yazma. Bu alt konu için mevcut kaynaklar yetersizse yeni kaynak ara; tam metni okunan kaynaklardan aktarımlarda sayfa numarası ver. Önceki alt başlıklarda yazılanları tekrar etme, konuya yeniden giriş yapma ve alt başlığı özet cümlesiyle bitirme; yalnızca bu alt başlığa özgü yeni bilgiyi yaz.": "Schreibe nur den Unterabschnitt „{h}“ dieses Abschnitts. Beginne den Entwurf mit der Überschrift „## {h}“; schreibe keine anderen Unterabschnitte. Wenn die vorhandenen Quellen für dieses Unterthema nicht ausreichen, suche neue; gib Seitenzahlen an, wenn du dich auf Quellen stützt, deren Volltext gelesen wurde. Wiederhole nicht, was frühere Unterüberschriften behandelt haben, führe das Thema nicht erneut ein und ende nicht mit einem zusammenfassenden Satz; schreibe nur, was für diese Unterüberschrift neu und spezifisch ist.",
  "Bu hafta": "Diese Woche",
  "Bu hafta {w} / {g} kelime": "Diese Woche {w} / {g} Wörter",
  "Bölüm başlıkları BÜYÜK HARF": "Kapitelüberschriften in GROSSBUCHSTABEN",
  "Bölüm başlıkları ortalı": "Kapitelüberschriften zentriert",
  "Chrome, Edge veya Safari’nin güncel sürümünü deneyin.": "Versuchen Sie eine aktuelle Version von Chrome, Edge oder Safari.",
  "Cihazda saklanan taslak geri yüklendi": "Auf dem Gerät gespeicherter Entwurf wiederhergestellt",
  "Danışman yorumu: “{c}”. Bu bölümün mevcut metnini bu yoruma göre nasıl düzeltmem gerektiğini açıkla; gerekiyorsa düzeltilmiş paragrafları taslak olarak ver.": "Kommentar der Betreuung: „{c}“. Erkläre, wie ich den aktuellen Text dieses Abschnitts nach diesem Kommentar überarbeiten sollte; gib die überarbeiteten Absätze bei Bedarf als Entwurf an.",
  "Danışman yorumu: “{c}”. Seçili metni bu yoruma göre düzelt; düzeltilmiş metni tek bir taslak olarak ver, mevcut atıfları koru. Yaptığın değişiklikleri kısaca açıkla.": "Kommentar der Betreuung: „{c}“. Überarbeite den ausgewählten Text nach diesem Kommentar; gib den überarbeiteten Text als einen einzigen Entwurf aus und behalte die bestehenden Zitate bei. Erläutere deine Änderungen kurz.",
  "Değerlendirme yapay zekâ tarafından yalnızca okunan kaynak metnine dayanarak yapılır; son karar sizindir.": "Die Bewertung erfolgt durch die KI ausschließlich auf Grundlage des gelesenen Quellentextes; die endgültige Entscheidung liegt bei Ihnen.",
