  "Her alt başlık bir yapay zekâ isteği sayılır; kaynak taramaları ayrıca sayılır. En fazla 12 alt başlık.": "Jede Unterüberschrift zählt als eine KI-Anfrage; Quellensuchen werden separat gezählt. Bis zu 12 Unterüberschriften.",
  "Her alt başlık bitince belgeye ekle": "Jede Unterüberschrift nach Fertigstellung ins Dokument einfügen",
  "Her bölüm yeni sayfada başlasın": "Jedes Kapitel auf einer neuen Seite beginnen",
  "Her kaynağın amacı, yöntemi, örneklemi ve bulguları yalnızca okunan özet veya tam metinden çıkarılır; metinde olmayan bilgi boş bırakılır. Yalnızca künyesi bilinen kaynaklar için içerik yazılmaz.": "Ziel, Methode, Stichprobe und Ergebnisse jeder Quelle werden ausschließlich aus dem gelesenen Abstract oder Volltext entnommen; nicht im Text enthaltene Angaben bleiben leer. Für Quellen mit nur bibliografischen Angaben wird nichts eingetragen.",
  "Her satıra bir alt başlık yazın. Asistan her alt başlık için ayrı ayrı kaynak tarar, açık erişimli tam metinleri okur ve o alt başlığı yazar. Bitince hangi alt başlıklarda kaynak bulunamadığını gösterir.": "Schreiben Sie eine Unterüberschrift pro Zeile. Für jede Unterüberschrift sucht der Assistent separat nach Quellen, liest Open-Access-Volltexte und schreibt den Unterabschnitt. Am Ende zeigt er, bei welchen Unterüberschriften Quellen fehlten.",
