  "Paragraf metinde bulunamadı (değiştirilmiş olabilir).": "Absatz im Text nicht gefunden (möglicherweise wurde er geändert).",
  "Paragraf sonrası boşluk": "Abstand nach Absatz",
  "Program": "Studiengang",
  "Projede {n} paragrafta “[KAYNAK GEREKLİ]” işareti var. Her biri için veri tabanlarında kaynak aranır; asistan paragrafı bulunan kaynaklarla destekler, kaynak bulunamazsa iddiayı yumuşatır. Hiçbir değişiklik onayınız olmadan uygulanmaz.": "{n} Absätze im Projekt enthalten „[KAYNAK GEREKLİ]“. Für jeden wird nach Quellen gesucht; der Assistent belegt den Absatz mit den gefundenen Quellen oder schwächt die Aussage ab, wenn keine gefunden werden. Ohne Ihre Zustimmung wird keine Änderung übernommen.",
  "Projede {n} yerde “[KAYNAK GEREKLİ]” var.": "„[KAYNAK GEREKLİ]“ kommt im Projekt an {n} Stellen vor.",
