  "ör.\nBağlanma kuramı\nİlişki odaklı OKB\nEbeveyn tutumları ve kişilik": "z. B.\nBindungstheorie\nBeziehungs-Zwangsstörung\nElterliche Erziehungseinstellungen und Persönlichkeit",
  "İki yana yasla": "Blocksatz",
  "İleri": "Weiter",
  "İlerleme": "Fortschritt",
  "Şablonu seçin, sonra üniversitenizin yazım kılavuzuna göre değerleri düzenleyin. Kılavuzu Proje ayarları’ndan yüklerseniz asistan da değerleri önerir.": "Wählen Sie eine Vorlage und passen Sie die Werte an die Schreibrichtlinien Ihrer Hochschule an. Wenn Sie die Richtlinie in den Projekteinstellungen hochladen, schlägt auch der Assistent Werte vor.",
