  "Hedef ve takvim": "Ziel und Zeitplan",
  "Dışa aktarma ve ayarlar": "Export und Einstellungen",
  "Çalışmanızın yol haritası. Bölümler arasında buradan geçersiniz; sürükleyerek sıralayabilir, yenisini ekleyebilirsiniz.": "Der Fahrplan Ihrer Arbeit. Hier wechseln Sie zwischen Abschnitten; ziehen Sie sie zum Neuordnen oder fügen Sie neue hinzu.",
  "Bölümü burada yazarsınız. Atıflar kaynağa bağlı canlı öğelerdir: üstüne tıklayınca sayfa ekleyebilir ve “Kaynakta doğrula” ile kaynağın gerçekten bunu söyleyip söylemediğini kontrol edebilirsiniz.": "Hier schreiben Sie den Abschnitt. Zitate sind mit der Quelle verknüpfte, lebendige Elemente: Klicken Sie auf eines, um eine Seite anzugeben, und prüfen Sie mit „In der Quelle prüfen“, ob die Quelle das wirklich sagt.",
  "Asistan gerektiğinde kaynakları kendisi arar, okur ve sayfa numarasıyla atıf yapar. “Alt başlıklarla yaz” ile bölümün tamamını alt başlık alt başlık yazdırabilir, mikrofonla sesli not verebilirsiniz.": "Der Assistent sucht und liest bei Bedarf Quellen und zitiert sie mit Seitenzahlen. Mit „Nach Unterüberschriften schreiben“ lassen Sie einen ganzen Abschnitt Unterüberschrift für Unterüberschrift schreiben, oder Sie diktieren Notizen per Mikrofon.",
  "Projedeki kaynaklar, erişim seviyeleri ve literatür matrisi burada. Tam metni okunamayan kaynaklar için PDF yükleyebilirsiniz.": "Hier finden Sie die Projektquellen, ihre Zugriffsstufen und die Literaturmatrix. Für Quellen, deren Volltext nicht gelesen werden konnte, können Sie PDFs hochladen.",
  "Kaynakça seçtiğiniz stile göre kendiliğinden oluşur. Bir kayda tıklayınca kullanıldığı yerleri görür, “Git” ile metindeki atfa gidersiniz.": "Das Literaturverzeichnis entsteht von selbst im gewählten Stil. Klicken Sie auf einen Eintrag, um zu sehen, wo er verwendet wird, und mit „Gehe zu“ springen Sie zum Zitat.",
  "Haftalık kelime hedefi ve teslim tarihi belirleyin; kalan bölümler haftalara dağıtılır.": "Legen Sie ein wöchentliches Wortziel und einen Abgabetermin fest; die verbleibenden Abschnitte werden auf die Wochen verteilt.",
  "Word/PDF çıktısı, üniversite biçim şablonu ve kapak bilgileri burada. Mobilde “⋯” menüsünde atıf stili, paylaşım ve dil seçimi de var.": "Hier finden Sie die Word-/PDF-Ausgabe, die Formatvorlage Ihrer Hochschule und die Angaben zum Titelblatt. Auf dem Smartphone enthält das Menü „⋯“ außerdem Zitierstil, Teilen und Sprache.",
  "Bu özellik için veritabanı güncellemesi gerekiyor (20261103000006_source_summary.sql).": "Für diese Funktion ist ein Datenbank-Update erforderlich (20261103000006_source_summary.sql).",
  "Dosya ve kaynak aynı projede olmalıdır": "Datei und Quelle müssen im selben Projekt liegen",
