  "Analizi çalıştır": "Analyse ausführen",
  "Analizler sunucuda gerçek hesaplamayla yapılır (SPSS ile aynı formüller); yapay zekâ hiçbir sayı üretmez. Sonuç APA 7 biçiminde tablo ve cümle olarak hazırlanır.": "Analysen werden auf dem Server mit echten Berechnungen ausgeführt (dieselben Formeln wie in SPSS); die KI erzeugt keine Zahlen. Die Ergebnisse werden als APA-7-Tabelle und -Satz aufbereitet.",
  "Arkadaşını davet et": "Freund:in einladen",
  "Arkadaşınız bu bağlantıyla kaydolup e-postasını doğruladığında ikinize de {a} yapay zekâ isteği ve {s} kaynak tarama hakkı ({d} gün geçerli).": "Wenn sich Ihre Freundin bzw. Ihr Freund über diesen Link registriert und die E-Mail-Adresse bestätigt, erhalten Sie beide {a} KI-Anfragen und {s} Quellensuchen (gültig für {d} Tage).",
