  "Bu projeye yüklenmiş veri dosyası (CSV/XLSX) yok. “Dosyalarım” sayfasından verinizi projeye bağlayarak yükleyin; ilk satır değişken adları olmalıdır.": "Für dieses Projekt wurde keine Datendatei (CSV/XLSX) hochgeladen. Laden Sie Ihre Daten auf der Seite „Meine Dateien“ hoch und verknüpfen Sie sie mit dem Projekt; die erste Zeile muss die Variablennamen enthalten.",
  "Davet bağlantısı": "Einladungslink",
  "Davet ettiğiniz her arkadaşınız e-postasını doğruladığında ikinize de {a} yapay zekâ isteği ve {s} kaynak tarama hakkı ({d} gün geçerli).": "Für jede eingeladene Person, die ihre E-Mail-Adresse bestätigt, erhalten Sie beide {a} KI-Anfragen und {s} Quellensuchen (gültig für {d} Tage).",
  "Davet ettiğiniz: {n} · ödül kazanan: {r}": "Eingeladen: {n} · belohnt: {r}",
  "Davetle geldiniz: e-postanızı doğruladığınızda size ve sizi davet edene ek yapay zekâ isteği ve kaynak tarama hakkı tanımlanır.": "Sie wurden eingeladen: Sobald Sie Ihre E-Mail-Adresse bestätigen, erhalten Sie und die einladende Person zusätzliche KI-Anfragen und Quellensuchen.",
