  "Fiyatlara KDV dahildir.": "Preise inklusive MwSt.",
  "Giriş yaptıktan sonra sol menüdeki “Geri bildirim” ile kurum adınızı, kullanıcı sayısını ve iletişim bilginizi gönderin; size dönelim.": "Senden Sie nach der Anmeldung den Namen Ihrer Institution, die Anzahl der Nutzenden und Ihre Kontaktdaten über „Feedback“ im linken Menü; wir melden uns bei Ihnen.",
  "Gizlilik: kurum yöneticileri üyelerin yalnızca kullanım sayılarını görür; proje başlıkları ve çalışma içerikleri kurumla paylaşılmaz.": "Datenschutz: Administratoren der Institution sehen nur die Nutzungszahlen der Mitglieder; Projekttitel und Inhalte werden nicht mit der Institution geteilt.",
