  "Tez türü": "Art der Abschlussarbeit",
  "Tez ve makale yazarken gerçek kaynaklarla çalışan bir akademik asistan kullanıyorum. Bu bağlantıyla kaydolursan ikimize de ek kullanım hakkı tanımlanıyor:": "Ich nutze für Abschlussarbeiten und Artikel einen wissenschaftlichen Assistenten, der mit echten Quellen arbeitet. Wenn du dich über diesen Link registrierst, bekommen wir beide zusätzliche Nutzung:",
