  "Yalnızca @{d} uzantılı e-postalar katılabilir.": "Nur E-Mail-Adressen mit @{d} können beitreten.",
  "Yalnızca Türkiye kaynakları (Türkçe ve Türkiye adresli yayınlar; DergiPark dahil)": "Nur türkische Quellen (türkischsprachige und Türkei-bezogene Publikationen; inkl. DergiPark)",
  "Yapay zekânın yetmediği yerde akademik uzmanlar: redaksiyon, istatistik, çeviri ve biçim kontrolü.": "Wissenschaftliche Fachleute, wo die KI nicht ausreicht: Lektorat, Statistik, Übersetzung und Formatprüfung.",
  "Yordayıcılar": "Prädiktoren",
  "YÖK Tez Merkezi’nde arama kutusuna yapıştırın. Bulduğunuz tezi “DOI / elle ekle” sekmesinden Tez türüyle ekleyin.": "Fügen Sie dies in das Suchfeld des YÖK-Thesenzentrums ein. Die gefundene Arbeit fügen Sie im Tab „DOI / manuell hinzufügen“ mit dem Typ „Hochschulschrift“ hinzu.",
