  "Üniversite e-postanızla (.edu.tr) kayıt olursanız ücretli paketlerde öğrenci indirimi uygulanır.": "Registrieren Sie sich mit Ihrer Hochschul-E-Mail-Adresse (.edu.tr), um bei kostenpflichtigen Tarifen den Studierendenrabatt zu erhalten.",
  "Üniversite e-postanızla (ör. @ogr.universite.edu.tr) kayıt olup e-postanızı doğruladığınızda ücretli paketlerde indirim ödeme sayfasında otomatik uygulanır.": "Registrieren Sie sich mit Ihrer Hochschul-E-Mail-Adresse (z. B. @ogr.universitaet.edu.tr) und bestätigen Sie sie; der Rabatt wird bei kostenpflichtigen Tarifen beim Bezahlen automatisch gewährt.",
  "Üniversite e-postasıyla (ör. {d} uzantılı) kayıtlı ve doğrulanmış hesaplarda ücretli paketlerde %{p} indirim uygulanır. Öğrenciyseniz üniversite e-postanızla yeni bir hesap açabilirsiniz.": "Konten, die mit einer Hochschul-E-Mail-Adresse (z. B. {d}) registriert und bestätigt wurden, erhalten {p} % Rabatt auf kostenpflichtige Tarife. Wenn Sie studieren, können Sie mit Ihrer Hochschul-E-Mail-Adresse ein neues Konto anlegen.",
