  "Burs başvurusu için araştırma önerisi (ör. 2211, 2214)": "Forschungsexposé für eine Stipendienbewerbung (z. B. 2211, 2214)",
  "Diğer kurum / fon": "Andere Institution / anderer Fonds",
  "Hakem yorumlarına cevap": "Antwort an die Gutachtenden",
  "Hakem yorumlarına cevap mektubu hazırla": "Antwortschreiben auf die Gutachterkommentare erstellen",
  "Cevap mektubu hazırla": "Antwortschreiben erstellen",
  "Dergiden gelen editör kararını ve hakem yorumlarını olduğu gibi yapıştırın. Asistan çalışmanızın mevcut hâlini okuyarak her yoruma madde madde cevap veren bir mektup hazırlar ve metinde yapmanız gereken değişiklikleri sıralar.": "Fügen Sie die Entscheidung der Herausgeberschaft und die Gutachterkommentare unverändert ein. Der Assistent liest die aktuelle Fassung Ihrer Arbeit, entwirft ein Schreiben, das jeden Kommentar Punkt für Punkt beantwortet, und listet die Änderungen auf, die Sie im Text vornehmen müssen.",
  "Reviewer 1:\n1. The sample size is small…\n2. …\n\nReviewer 2:\n…": "Gutachter:in 1:\n1. Die Stichprobe ist klein …\n2. …\n\nGutachter:in 2:\n…",
  "Henüz yapmadığınız değişiklikler mektupta [YAPILACAK: …] olarak işaretlenir; sayfa numaraları sizin doldurmanız için boş bırakılır.": "Noch nicht vorgenommene Änderungen werden im Schreiben mit [ZU ERLEDIGEN: …] markiert; Seitenzahlen bleiben leer, damit Sie sie eintragen.",
  "Savunma provası": "Probe der Verteidigung",
  "Destekleyici": "Wohlwollend",
  "Standart jüri": "Übliche Prüfungskommission",
  "Zorlayıcı": "Anspruchsvoll",
  "Yapay zekâ jüri, çalışmanızın metnini okuyup savunmada sorulabilecek soruları hazırlar. Her soruya yazarak veya konuşarak cevap verin; cevabınızın güçlü ve eksik yönlerini ve daha iyi bir cevabın iskeletini görün.": "Die KI-Prüfungskommission liest Ihre Arbeit und bereitet Fragen vor, die Ihnen in der Verteidigung gestellt werden könnten. Beantworten Sie jede Frage schriftlich oder mündlich; Sie sehen Stärken und Lücken Ihrer Antwort sowie die Gliederung einer stärkeren Antwort.",
  "Jüri tutumu": "Stil der Kommission",
  "Soru sayısı": "Anzahl der Fragen",
