  "Sorular yalnızca çalışmanızda yazılı olanlara dayanır. Konuşarak cevap verirken ses tarayıcınızda yazıya çevrilir, ses kaydı sunucuya gönderilmez.": "Die Fragen beruhen ausschließlich auf dem, was in Ihrer Arbeit steht. Wenn Sie mündlich antworten, wird Ihre Stimme im Browser transkribiert; es wird kein Audio an den Server gesendet.",
