  "Ayarlara dön": "Zurück zu den Einstellungen",
  "Bu projeye yüklenmiş veri dosyası (CSV/XLSX) yok. “Dosyalarım” sayfasından verinizi projeye bağlayarak yükleyin veya anket cevaplarınızı projeye aktarın; ilk satır değişken adları olmalıdır.": "Für dieses Projekt ist keine Datendatei (CSV/XLSX) hochgeladen. Laden Sie Ihre Daten unter „Meine Dateien“ mit dem Projekt verknüpft hoch oder senden Sie Ihre Umfrageantworten an das Projekt; die erste Zeile muss die Variablennamen enthalten.",
  "Şekil başlığı": "Titel der Abbildung",
  "Not.": "Anmerkung.",
  "Grafik, verinizden gerçek hesaplamayla ve APA 7 şekil kurallarına uygun (siyah-beyaz, eksen başlıklı, numaralı) çizilir. Word ve PDF çıktısına görsel olarak eklenir.": "Das Diagramm wird aus Ihren Daten mit echten Berechnungen gezeichnet und folgt den APA-7-Regeln für Abbildungen (schwarz-weiß, Achsentitel, nummeriert). In Word- und PDF-Exporten wird es als Bild eingebettet.",
