  "Ölçek ve anketlerinizi hazırlayın, bağlantıyla katılımcılara gönderin; cevaplar tek tıkla istatistik analizine ve grafiklere aktarılır.": "Erstellen Sie Ihre Skalen und Umfragen und senden Sie sie per Link an Teilnehmende; die Antworten gehen mit einem Klick in die statistische Auswertung und in Diagramme.",
