  "Sorular": "Fragen",
  "Cevaplar": "Antworten",
  "Bu anket cevap almaya başladı. Veri sütunları bozulmasın diye soru ekleyip çıkaramaz, seçenek sayısını değiştiremezsiniz; yalnızca yazım düzeltmesi yapabilirsiniz. Yeni sorular için anketin kopyasını oluşturun.": "Für diese Umfrage gehen bereits Antworten ein. Damit die Datenspalten erhalten bleiben, können Sie keine Fragen hinzufügen oder entfernen und die Anzahl der Antwortoptionen nicht ändern; nur Tippfehler lassen sich korrigieren. Für neue Fragen legen Sie eine Kopie der Umfrage an.",
  "Kopya oluştur": "Kopie anlegen",
  "Aşağıdaki düğmelerle soru ekleyin. Hazır bir ölçek kullanacaksanız maddelerini “Likert ölçeği” ile tek seferde yapıştırabilirsiniz.": "Fügen Sie mit den Schaltflächen unten Fragen hinzu. Wenn Sie eine vorhandene Skala verwenden, fügen Sie mit „Likert-Skala“ alle Items auf einmal ein.",
  "Demografik sorular ekle": "Demografische Fragen hinzufügen",
  "Başkasına ait bir ölçeği kullanıyorsanız (ör. uyarlanmış ölçekler), çoğu zaman ölçek sahibinden yazılı kullanım izni almanız gerekir. Anketi uygulamadan önce kurumunuzun etik kurul onayını almayı unutmayın.": "Wenn Sie die Skala einer anderen Person verwenden (z. B. adaptierte Skalen), benötigen Sie in der Regel eine schriftliche Genehmigung der Rechteinhaber. Denken Sie daran, vor der Befragung ein Ethikvotum Ihrer Institution einzuholen.",
  "Açıklama (katılımcılar formun başında görür)": "Beschreibung (wird oben im Formular angezeigt)",
