  "Çok yoğun bir an; lütfen birkaç saniye sonra tekrar gönderin.": "Gerade ist sehr viel los; bitte senden Sie in ein paar Sekunden erneut.",
  "Cevap almaya başlamış bir anketin soru yapısı değiştirilemez. Yalnızca yazım düzeltmesi yapabilirsiniz; yeni sorular için anketin kopyasını oluşturun.": "Die Fragenstruktur einer Umfrage, für die bereits Antworten eingehen, kann nicht geändert werden. Nur Tippfehler lassen sich korrigieren; für neue Fragen legen Sie eine Kopie der Umfrage an.",
  "Yayına almadan önce en az bir soru ekleyin": "Fügen Sie vor dem Veröffentlichen mindestens eine Frage hinzu",
  "Henüz cevap yok": "Noch keine Antworten",
  "Konu bulma": "Themenfinder",
  "Tez konusu bulma": "Themenfinder für Abschlussarbeiten",
  "Bir alan veya anahtar kelime yazın: OpenAlex’teki gerçek yayın kayıtlarından yıllara göre eğilimi, yükselen alt konuları ve Türkiye’de ne kadar çalışıldığını görün. Yapay zekâ bu verilere dayanarak konu önerileri çıkarır.": "Geben Sie ein Fachgebiet oder Schlüsselwort ein: Sie sehen auf Basis echter Publikationsdaten aus OpenAlex den Verlauf über die Jahre, aufstrebende Unterthemen und wie stark das Thema in der Türkei erforscht wird. Die KI schlägt auf Grundlage dieser Daten Themen vor.",
  "ör. lithium-ion battery degradation (İngilizce daha çok sonuç verir)": "z. B. Alterung von Lithium-Ionen-Batterien",
