  "Kapsam:": "Umfang:",
  "Bu konuyla tez başlat": "Abschlussarbeit zu diesem Thema beginnen",
  "Öneriler bir başlangıç noktasıdır. Konuyu seçmeden önce danışmanınızla görüşün ve “Kaynak araştırması” ile literatürü ayrıntılı tarayın; veriler arama kelimelerine bağlıdır.": "Die Vorschläge sind ein Ausgangspunkt. Sprechen Sie vor der Themenwahl mit Ihrer Betreuung und sichten Sie die Literatur mit der „Quellenrecherche“ gründlich; die Daten hängen von den Suchbegriffen ab.",
  "Konu önerileri şu anda oluşturulamadı; istatistikler yine de gerçek verilere dayanır.": "Themenvorschläge konnten gerade nicht erstellt werden; die Statistiken beruhen dennoch auf echten Daten.",
  "Son 5 yılın en çok atıf alan çalışmaları": "Meistzitierte Arbeiten der letzten 5 Jahre",
  "Veri tabanına şu anda ulaşılamadı, lütfen biraz sonra tekrar deneyin": "Die Datenbank war gerade nicht erreichbar, bitte versuchen Sie es gleich erneut",
  "Öneriler oluşturulamadı, lütfen tekrar deneyin": "Vorschläge konnten nicht erstellt werden, bitte versuchen Sie es erneut",
  "Anketin adı": "Name der Umfrage",
  "Cevaplar hangi çalışmanızda kullanılacak? (isteğe bağlı)": "Welches Ihrer Projekte nutzt die Antworten? (optional)",
  "Şimdilik hiçbir çalışmaya bağlama": "Vorerst mit keinem Projekt verknüpfen",
  "Listede kendi tez ve makale çalışmalarınız görünür. Seçerseniz anket cevaplarını o çalışmaya tek tıkla aktarıp istatistik analizi ve grafik yapabilirsiniz. Daha sonra da değiştirebilirsiniz.": "Die Liste zeigt Ihre eigenen Projekte (Abschlussarbeiten und Artikel). Wenn Sie eines wählen, können Sie die Umfrageantworten mit einem Klick für statistische Auswertung und Diagramme dorthin senden. Sie können dies später ändern.",
  "Anketi oluştur": "Umfrage erstellen",
  "Cevapların kullanılacağı çalışma": "Projekt, das die Antworten nutzt",
  "Adım 1: Başlık seç": "Schritt 1: Titel wählen",
  "Adım 1: Çalışmanızın başlığını seçin": "Schritt 1: Wählen Sie Ihren Titel",
  "Başlık kaydedildi": "Titel gespeichert",
  "Başlık seçildi": "Titel gewählt",
  "Başlık önerileri hazırlanıyor…": "Titelvorschläge werden vorbereitet …",
  "Başlık, çalışmanın neyi, kimde ve nasıl incelediğini gösterir; sonraki bütün bölümler buna göre yazılır. Konunuza göre hazırlanan önerilerden birini seçin veya düzenleyin. Başlığı daha sonra da değiştirebilirsiniz.": "Der Titel zeigt, was Ihre Studie bei wem und wie untersucht; alle folgenden Abschnitte werden um ihn herum geschrieben. Wählen oder bearbeiten Sie einen der für Ihr Thema vorbereiteten Vorschläge. Sie können den Titel später ändern.",
  "Bu başlıkla devam et": "Mit diesem Titel fortfahren",
  "Bölüm tamamlandı": "Abschnitt abgeschlossen",
  "Bölümü tamamladım": "Abschnitt als abgeschlossen markieren",
  "Kalite kontrolünü çalıştırıp çalışmanızı Word veya PDF olarak indirebilirsiniz.": "Führen Sie die Qualitätsprüfung durch und laden Sie Ihre Arbeit als Word oder PDF herunter.",
  "Seçilen başlık (dilediğiniz gibi düzenleyebilirsiniz)": "Gewählter Titel (nach Belieben bearbeiten)",
  "Sonra seçeceğim": "Ich wähle später",
  "Sıradaki": "Weiter",
  "Sıradaki adım: {s}": "Nächster Schritt: {s}",
  "Sıradaki bölüm: {s}": "Nächster Abschnitt: {s}",
  "Sıradakine git: {s}": "Weiter zu: {s}",
  "Tüm bölümler tamamlandı!": "Alle Abschnitte abgeschlossen!",
  "Yeni öneriler": "Neue Vorschläge",
  "en son yazılır": "wird zuletzt geschrieben",
  "{d}/{n} bölüm tamamlandı": "{d}/{n} Abschnitte abgeschlossen",
  "Önce bölümü yazın": "Schreiben Sie zuerst den Abschnitt",
  "Öneri al": "Vorschläge abrufen",
  "Özet, çalışmanın tamamı yazıldıktan sonra yazılır; çünkü bütün bölümleri özetler. Önce sıradaki bölümü tamamlayın.": "Das Abstract wird nach der gesamten Arbeit geschrieben, weil es alle Abschnitte zusammenfasst. Schließen Sie zuerst den nächsten Abschnitt ab.",
  "İsteğinizi yazın (ör. daha kısa olsun, ortaokul öğrencileriyle sınırla)": "Beschreiben Sie, was Sie möchten (z. B. kürzer, auf Schülerinnen und Schüler der Sekundarstufe I begrenzen)",
  "“{s}” tamamlandı": "„{s}“ abgeschlossen",
  "Başlık önerileri oluşturulamadı, lütfen tekrar deneyin": "Titelvorschläge konnten nicht erstellt werden, bitte versuchen Sie es erneut",
  "Başlık önerileri oluşturulamadı": "Titelvorschläge konnten nicht erstellt werden",
  "Asistanla düzelt": "Mit Assistent korrigieren",
  "Bu bölümün kontrolünde şu sorunlar bulundu:\n{list}\n\nBölümü bu sorunları giderecek şekilde düzelt. Düzeltilmiş bölümü taslak olarak ver; mevcut atıfları ve sayfa bilgilerini koru, yeni bilgi veya kaynak uydurma. Neyi değiştirdiğini kısaca yaz.": "Bei der Prüfung dieses Abschnitts wurden folgende Probleme gefunden:\n{list}\n\nÜberarbeite den Abschnitt, um sie zu beheben. Gib den überarbeiteten Abschnitt als Entwurf aus; behalte bestehende Zitate und Seitenzahlen bei und erfinde keine neuen Informationen oder Quellen. Beschreibe kurz, was du geändert hast.",
  "Bulunan sorunlar ({n})": "Gefundene Probleme ({n})",
  "Bölüm kontrol ediliyor: kaynak işaretleri, tekrarlar, akademik dil ve bölümün amacına uygunluk…": "Abschnitt wird geprüft: Quellenmarkierungen, Wiederholungen, Wissenschaftssprache und Passung zum Zweck des Abschnitts …",
  "Bölüm kontrolü: {s}": "Abschnittsprüfung: {s}",
  "Bölüm uygun görünüyor": "Der Abschnitt sieht gut aus",
