  "Bölümde {n} yerde “[VERİ GİRİLECEK]” var.": "Der Abschnitt enthält an {n} Stellen „[VERİ GİRİLECEK]“.",
  "Bölümde önemli eksikler var": "Der Abschnitt weist wichtige Lücken auf",
