  "Kendi verilerinizi girin; yapay zekâ veri üretmez.": "Geben Sie Ihre eigenen Daten ein; die KI erzeugt keine Daten.",
  "Kontrol yapılamadı:": "Die Prüfung konnte nicht abgeschlossen werden:",
  "Kontrol yol göstericidir; son karar sizin ve danışmanınızındır.": "Die Prüfung dient der Orientierung; die endgültige Entscheidung liegt bei Ihnen und Ihrer Betreuung.",
  "Küçük düzeltmeler önerilir": "Kleinere Überarbeitungen empfohlen",
