  "Bugünkü yapay zekâ bölüm kontrolü sınırına ulaşıldı; yarın tekrar deneyebilirsiniz": "Das heutige Limit für KI-Abschnittsprüfungen ist erreicht; Sie können es morgen erneut versuchen",
