  "“Yükle”ye dokunun. Academiana simgesi ana ekranınıza gelir.": "Tippen Sie auf „Installieren“. Das Academiana-Symbol erscheint auf Ihrem Startbildschirm.",
  "Safari’de üst menüden “Dosya”yı açın (veya Paylaş düğmesine tıklayın).": "Öffnen Sie in Safari oben das Menü „Ablage“ (oder klicken Sie auf die Schaltfläche „Teilen“).",
