  "“Ekle”ye tıklayın. Academiana, Dock’ta ayrı bir uygulama olarak açılır.": "Klicken Sie auf „Hinzufügen“. Academiana öffnet sich als eigene App aus dem Dock.",
  "Chrome veya Edge kullanın.": "Verwenden Sie Chrome oder Edge.",
  "Adres çubuğunun sağındaki kurulum simgesine (ekran ve ok) tıklayın ya da sağ üstteki menüden “Academiana’yı yükle” / “Uygulamayı yükle”yi seçin.": "Klicken Sie rechts in der Adressleiste auf das Installationssymbol (Bildschirm mit Pfeil) oder wählen Sie im Menü oben rechts „Academiana installieren“ / „App installieren“.",
  "“Yükle”ye tıklayın. Academiana masaüstünüzde ve başlat menüsünde ayrı bir uygulama olarak açılır.": "Klicken Sie auf „Installieren“. Academiana öffnet sich als eigene App vom Desktop und aus dem Startmenü.",
  "Akademik yazım rehberleri": "Leitfäden zum wissenschaftlichen Schreiben",
  "Blog": "Blog",
