  "Bütün yazılar": "Alle Beiträge",
  "Gerçek kaynaklarla çalışan akademik asistan. Kredi kartı gerekmez.": "Ein wissenschaftlicher Assistent, der mit echten Quellen arbeitet. Keine Kreditkarte erforderlich.",
  "Kategoriler": "Kategorien",
  "Tez nasıl yazılır, APA 7 atıf kuralları, literatür taraması, intihalden kaçınma, istatistik analiz seçimi, TÜBİTAK başvurusu ve daha fazlası.": "Wie man eine Abschlussarbeit schreibt, Zitierregeln nach APA 7, Literaturrecherche, Plagiate vermeiden, den richtigen statistischen Test wählen, TÜBİTAK-Anträge und mehr.",
  "Tez, makale ve araştırma sürecinde en çok merak edilen soruların cevapları: adım adım, örneklerle ve sade bir dille.": "Antworten auf die häufigsten Fragen zu Abschlussarbeiten, Artikeln und Forschung: Schritt für Schritt, mit Beispielen und in verständlicher Sprache.",
