  "TÜBİTAK 2209-A başvurusu": "TÜBİTAK-2209-A-Antrag",
  "Kurumlar": "Institutionen",
  "Merhaba, Academiana Akademik Ekip İndirimi (%{p}) hakkında bilgi almak istiyorum.\nKurum / bölüm / ekip adı: \nKişi sayısı: \nİlgilendiğimiz paket: ": "Hallo, ich hätte gern Informationen zum Academiana-Rabatt für akademische Teams ({p} %).\nInstitution / Fachbereich / Team: \nAnzahl der Personen: \nGewünschter Tarif: ",
  "Merhaba, Academiana Akademik Ekip İndirimi (%{p}) hakkında bilgi almak istiyorum.\nKurum / bölüm / ekip adı: \nKişi sayısı: \nİlgilendiğimiz paket: \nÜye no: {no}\nHesap e-postam: {email}": "Hallo, ich hätte gern Informationen zum Academiana-Rabatt für akademische Teams ({p} %).\nInstitution / Fachbereich / Team: \nAnzahl der Personen: \nGewünschter Tarif: \nMitgliedsnummer: {no}\nE-Mail-Adresse des Kontos: {email}",
  "Merhaba, Academiana kurum lisansı / Akademik Ekip İndirimi için teklif almak istiyorum.\nKurum / bölüm / ekip adı: \nKişi sayısı: \nİlgilendiğimiz paket: ": "Hallo, ich hätte gern ein Angebot für eine Academiana-Institutionslizenz / den Rabatt für akademische Teams.\nInstitution / Fachbereich / Team: \nAnzahl der Personen: \nGewünschter Tarif: ",
  "Merhaba, Academiana’da paketimi yükseltmek istiyorum.\nMevcut paketim: {current}\nGeçmek istediğim paket: {target} ({price}/ay)\nÜye no: {no}\nHesap e-postam: {email}": "Hallo, ich möchte meinen Academiana-Tarif upgraden.\nAktueller Tarif: {current}\nGewünschter Tarif: {target} ({price}/Monat)\nMitgliedsnummer: {no}\nE-Mail-Adresse des Kontos: {email}",
  "Limitler yapay zekâ istekleri, kaynak taramaları, proje sayısı ve depolama üzerinden belirlenir. Taahhüt yok; ücretsiz paketle başlayıp istediğiniz zaman yükseltebilirsiniz.": "Die Limits richten sich nach KI-Anfragen, Quellensuchen, Anzahl der Projekte und Speicherplatz. Keine Vertragsbindung: Starten Sie kostenlos und upgraden Sie, wann Sie möchten.",
  "Akademik Ekip İndirimi: %{p}": "Rabatt für akademische Teams: {p} %",
  "Akademisyen grupları, araştırma ekipleri, laboratuvarlar ve bölümler için: en az {n} kişilik ekiplerde tüm ücretli paketlerde %{p} indirim.": "Für Lehrstuhlgruppen, Forschungsteams, Labore und Fachbereiche: {p} % Rabatt auf alle kostenpflichtigen Tarife für Teams ab {n} Personen.",
  "WhatsApp’tan bilgi al →": "Per WhatsApp anfragen →",
  "WhatsApp’tan bilgi al": "Per WhatsApp anfragen",
  "WhatsApp:": "WhatsApp:",
  "Paket yükseltme şimdilik WhatsApp üzerinden yapılıyor: “Yükselt”e bastığınızda mevcut paketinizi ve seçtiğiniz paketi içeren hazır bir mesaj açılır. Gönderdiğinizde size dönüş yapılır ve paketiniz hesabınıza tanımlanır.": "Upgrades werden derzeit über WhatsApp abgewickelt: Mit „Upgrade“ öffnet sich eine vorbereitete Nachricht mit Ihrem aktuellen und dem gewählten Tarif. Sobald Sie sie senden, melden wir uns und schalten den Tarif in Ihrem Konto frei.",
  "Aylık 20 yapay zekâ isteği": "20 KI-Anfragen pro Monat",
  "Aylık 7 kaynak taraması": "7 Quellensuchen pro Monat",
  "Tek Proje maliyet uyarısı": "Kostenwarnung Einzelprojekt",
  "{u} için yapay zekâ maliyeti paket gelirinin %{p}’ine ulaştı ({c} $; %40 sınırı {b} $). Kullanım kısıtlanmadı.": "Die KI-Kosten für {u} haben {p} % des Tarifumsatzes erreicht (${c}; 40-%-Schwelle ${b}). Die Nutzung wurde nicht eingeschränkt.",
  "tek ödeme": "einmalig",
  "Tek Proje": "Einzelprojekt",
  "Tek bir çalışma için tek ödeme: süresiz ve sınırsız kullanım.": "Eine Zahlung für eine einzelne Arbeit: ohne Zeitlimit, unbegrenzte Nutzung.",
  "Tek seferlik ödeme, süre sınırı yok": "Einmalzahlung, ohne Zeitlimit",
  "1 çalışma (tez, makale, proje önerisi…)": "1 Arbeit (Abschlussarbeit, Artikel, Exposé …)",
