  "Ayrıntı: Yönetim → Kullanıcılar → kullanıcı → Kullanım geçmişi.": "Details: Admin → Nutzende → Person → Nutzungsverlauf.",
  "{u} ikinci bir çalışma açmaya çalıştı (engellendi).": "{u} hat versucht, eine zweite Arbeit anzulegen (blockiert).",
  "{u} pakete bağlı çalışmasını silmeye çalıştı (engellendi).": "{u} hat versucht, die an den Tarif gebundene Arbeit zu löschen (blockiert).",
  "{u} çalışma türünü değiştirmeye çalıştı (engellendi).": "{u} hat versucht, die Art der Arbeit zu ändern (blockiert).",
  "{u} çalışmasını indirdikten sonra {w} kelime sildi. Bitirip yeni bir çalışmaya geçiyor olabilir.": "{u} hat nach dem Herunterladen der Arbeit {w} Wörter gelöscht. Möglicherweise wird sie abgeschlossen und eine andere begonnen.",
  "{u} çalışmasından toplam {w} kelime sildi (ürettiğinin büyük kısmı).": "{u} hat insgesamt {w} Wörter aus der Arbeit gelöscht (den Großteil des Erzeugten).",
  "{u} çalışmanın başlığını veya konusunu tamamen değiştirdi: “{o}” → “{n}”.": "{u} hat Titel oder Thema der Arbeit vollständig geändert: „{o}“ → „{n}“.",
  "{u} toplam {w} kelime yapay zekâ metni üretti (birden fazla tez büyüklüğünde).": "{u} hat insgesamt {w} Wörter KI-Text erzeugt (mehr als der Umfang einer Abschlussarbeit).",
  "Davet ödülü verilmedi": "Empfehlungsprämie nicht gewährt",
  "Davet bağlantınızla açılan hesap, sizin daha önce kullandığınız bir cihazdan kaydolduğu için ödül tanımlanmadı. Davet ödülü yalnızca başka kişilerin kendi cihazlarından kaydolmasıyla kazanılır.": "Das über Ihren Einladungslink erstellte Konto wurde auf einem Gerät registriert, das Sie bereits genutzt haben; daher wurde keine Prämie gewährt. Empfehlungsprämien gibt es nur, wenn sich andere Personen auf ihren eigenen Geräten registrieren.",
  "Bildirimler": "Benachrichtigungen",
  "Bildirim": "Benachrichtigung",
  "Henüz bildirim yok.": "Noch keine Benachrichtigungen.",
  "Davet ödülü kazandınız": "Sie haben eine Empfehlungsprämie erhalten",
  "Davet ettiğiniz bir kişi kaydoldu. Hesabınıza bir Ücretsiz paket kadar hak tanımlandı: {p} sayfa, {a} yapay zekâ isteği ve {s} kaynak tarama ({d} gün geçerli).": "Eine von Ihnen eingeladene Person hat sich registriert. Ihrem Konto wurde das Kontingent eines Free-Pakets gutgeschrieben: {p} Seiten, {a} KI-Anfragen und {s} Quellensuchen (gültig für {d} Tage).",
  "Davetiniz kaydoldu": "Ihre eingeladene Person hat sich registriert",
  "Davet ettiğiniz bir kişi kaydoldu, ancak bu ayki davet ödülü sınırına ({n}) ulaştığınız için ödül tanımlanmadı. Sınır her ayın başında yenilenir.": "Eine von Ihnen eingeladene Person hat sich registriert, es wurde aber keine Prämie gutgeschrieben, weil Sie das Monatslimit für Empfehlungsprämien ({n}) erreicht haben. Das Limit wird zu Beginn jedes Monats zurückgesetzt.",
  "Arkadaşını davet et, kazan": "Freund:innen einladen, Prämie erhalten",
  "Davet ettiğin her arkadaş kaydolduğunda sana bir Ücretsiz paket kadar hak tanımlanır: {p} sayfa, {a} yapay zekâ isteği ve {s} kaynak tarama ({d} gün geçerli).": "Für jede eingeladene Person, die sich registriert, erhältst du das Kontingent eines Free-Pakets: {p} Seiten, {a} KI-Anfragen und {s} Quellensuchen (gültig für {d} Tage).",
  "Arkadaşını davet et, ek hak kazan!": "Freund:innen einladen und zusätzliche Nutzung erhalten!",
  "Arkadaşınız bu bağlantıyla kaydolduğunda size bir Ücretsiz paket kadar hak tanımlanır: {p} sayfa, {a} yapay zekâ isteği ve {s} kaynak tarama ({d} gün geçerli).": "Wenn sich Ihre Freundin bzw. Ihr Freund über diesen Link registriert, erhalten Sie das Kontingent eines Free-Pakets: {p} Seiten, {a} KI-Anfragen und {s} Quellensuchen (gültig für {d} Tage).",
  "Davet ettiğiniz her arkadaşınız kaydolduğunda size bir Ücretsiz paket kadar hak tanımlanır: {p} sayfa, {a} yapay zekâ isteği ve {s} kaynak tarama ({d} gün geçerli).": "Für jede eingeladene Person, die sich registriert, erhalten Sie das Kontingent eines Free-Pakets: {p} Seiten, {a} KI-Anfragen und {s} Quellensuchen (gültig für {d} Tage).",
  "Davetle geldiniz: kaydolduğunuzda sizi davet eden kişiye ek kullanım hakkı tanımlanır. Siz de Ücretsiz paketin tüm haklarıyla başlarsınız.": "Sie kommen über eine Einladung: Wenn Sie sich registrieren, erhält die einladende Person zusätzliche Nutzung. Sie starten mit allem, was der Free-Tarif bietet.",
  "Taslak {w} kelimede kaldı; kurgudaki hedefe ({t} kelime) tamamlanıyor…": "Der Entwurf endete bei {w} Wörtern; er wird auf das Ziel aus dem Konzept ({t} Wörter) ergänzt …",
  "Taslak {w} kelime (kurgudaki hedef {t} kelime).": "Entwurf: {w} Wörter (Ziel laut Konzept {t} Wörter).",
