  "Yapay zekâ ile yaklaşık 5 sayfa deneme taslağı": "Etwa 5 Seiten KI-gestützter Probeentwurf",
  "Ayda yaklaşık 25 sayfa yapay zekâ destekli akademik metin (ör. 1 makale veya tezin 2–3 bölümü)": "Etwa 25 Seiten KI-gestützter wissenschaftlicher Text pro Monat (z. B. 1 Artikel oder 2–3 Kapitel einer Abschlussarbeit)",
  "Ayda yaklaşık 50 sayfa yapay zekâ destekli akademik metin (ör. 2 makale; yüksek lisans tezi 1–2 ayda)": "Etwa 50 Seiten KI-gestützter wissenschaftlicher Text pro Monat (z. B. 2 Artikel; eine Masterarbeit in 1–2 Monaten)",
  "Ayda yaklaşık 85 sayfa yapay zekâ destekli akademik metin (yüksek lisans tezi ayda bir; doktora tezi yaklaşık 2 ayda)": "Etwa 85 Seiten KI-gestützter wissenschaftlicher Text pro Monat (eine Masterarbeit pro Monat; eine Dissertation in etwa 2 Monaten)",
  "Sınırsız kaynak taraması (adil kullanım)": "Unbegrenzte Quellensuchen (Fair Use)",
  "Ayda yaklaşık {n} sayfa akademik metin": "Etwa {n} Seiten wissenschaftlicher Text pro Monat",
  "“Sayfa”: Türk tez biçiminde (Times New Roman 12 punto, 1,5 satır aralığı) yapay zekâ desteğiyle yazılan ana metin sayfası; kapak, içindekiler, kaynakça ve ekler sayılmaz. Değerler yaklaşıktır: taslakları sık yeniden yazdırmak daha az, verimli kullanım daha fazla sayfa sağlar.": "„Seite“: eine KI-gestützt geschriebene Seite Haupttext im Format einer türkischen Abschlussarbeit (Times New Roman 12 pt, Zeilenabstand 1,5); Titelblatt, Inhaltsverzeichnis, Literaturverzeichnis und Anhänge werden nicht mitgezählt. Die Werte sind Richtwerte: Häufiges Neu-Erzeugen von Entwürfen ergibt weniger Seiten, effiziente Nutzung mehr.",
  "3 proje": "3 Projekte",
  "10 proje": "10 Projekte",
  "Aylık 150 yapay zekâ isteği": "150 KI-Anfragen pro Monat",
  "Aylık 100 kaynak taraması": "100 Quellensuchen pro Monat",
  "Aylık 2.000 kaynak taraması": "2.000 Quellensuchen pro Monat",
  "Aylık 8.000 kaynak taraması": "8.000 Quellensuchen pro Monat",
  "Her paket, çalışmanızın aşamasına uygun araçlar içerir. Taahhüt yok; ücretsiz başlayıp istediğiniz zaman yükseltebilirsiniz.": "Jeder Tarif enthält die Werkzeuge, die Ihre Arbeitsphase braucht. Keine Vertragsbindung: Starten Sie kostenlos und upgraden Sie, wann Sie möchten.",
  "Yapay zekâ kullanımında paketlere göre aylık adil kullanım sınırları uygulanır; sınırlar paket yükseltirken gösterilir.": "Je nach Tarif gelten monatliche Fair-Use-Limits für die KI-Nutzung; die Limits werden beim Upgrade angezeigt.",
  "Paket yükseltme şimdilik WhatsApp üzerinden yapılıyor: “Yükselt”e bastığınızda paketin kullanım sınırlarını görür, ardından hazır bir mesajla WhatsApp’a geçersiniz. Ödemeniz alındıktan sonra paketiniz hesabınıza tanımlanır.": "Upgrades werden derzeit über WhatsApp abgewickelt: Mit „Upgrade“ sehen Sie die Nutzungslimits des Tarifs und gelangen dann mit einer vorbereiteten Nachricht zu WhatsApp. Ihr Tarif wird nach der Zahlung freigeschaltet.",
