  "Var olmayan kaynak ve DOI üretebilir; doğrulamak sana kalır": "Können nicht existierende Quellen und DOIs erfinden; die Prüfung bleibt Ihnen überlassen",
  "Kaynağı olmayan iddiayı yazmaz, [KAYNAK GEREKLİ] diye işaretler": "Schreibt nie eine unbelegte Aussage – sie wird als [CITATION NEEDED] markiert",
  "Boşlukları ikna edici ama dayanaksız cümlelerle doldurabilir": "Füllen Lücken womöglich mit überzeugenden, aber unbelegten Sätzen",
  "Tez ve makale bölüm bölüm, akademik iskelet ve bölüm kontrolüyle ilerler": "Abschlussarbeiten und Artikel entstehen Abschnitt für Abschnitt, mit wissenschaftlicher Struktur und Abschnittsprüfungen",
  "Genelde tek blok metin verir; bölüm yapısı ve ilerleme takibi yok": "Liefern meist einen einzigen Textblock; keine Abschnittsstruktur und keine Fortschrittsverfolgung",
