  "Paragraftaki her atıf gerçek bir kaynağa bağlanır: atıfa dokun, kaynağı ve doğrulamasını gör. Kaynağı olmayan iddia sessizce yazılmaz; işaretlenir.": "Jedes Zitat in einem Absatz ist mit einer echten Quelle verknüpft: Tippen Sie darauf, um die Quelle und ihre Verifizierung zu sehen. Eine Aussage ohne Quelle wird nicht stillschweigend geschrieben – sie wird markiert.",
