  "Örnek gösterimdir; listelenen kaynaklar gerçek yayınlardır. Bir atıfın veya kaynağın üzerine gelerek doğrulamayı görün.": "Beispieldarstellung; die aufgeführten Quellen sind echte Publikationen. Fahren Sie mit der Maus über ein Zitat oder eine Quelle, um die Verifizierung zu sehen.",
  "Uzaktan eğitimde öğrencilerin öz düzenleme becerileri, ders başarısının en güçlü yordayıcılarından biridir": "Im Fernunterricht gehören die Selbstregulationsfähigkeiten der Studierenden zu den stärksten Prädiktoren für den Kurserfolg",
  "Eş zamanlı canlı derslerin öğrencilerin derse bağlılığını artırdığı bildirilmektedir": "Synchrone Live-Veranstaltungen sollen das Engagement der Studierenden erhöhen",
  "Öğretmenden alınan zamanında geri bildirim ise bu ilişkide aracı bir rol üstlenmektedir": "Zeitnahes Feedback der Lehrkraft wiederum spielt in diesem Zusammenhang eine vermittelnde Rolle",
