  "öz düzenleme becerilerinin uzaktan eğitimde ders başarısını en güçlü biçimde yordayan değişken olduğunu": "zeigten, dass Selbstregulationsfähigkeiten der stärkste Prädiktor für den Kurserfolg im Fernunterricht waren",
  " göstermiştir.": ".",
  "Canlı derslere katılan öğrencilerin derse bağlılık puanları, yalnızca kayıtlı videolarla çalışan öğrencilere göre anlamlı düzeyde yüksektir": "Studierende, die an Live-Veranstaltungen teilnahmen, hatten signifikant höhere Engagement-Werte als Studierende, die nur mit aufgezeichneten Videos lernten",
  "Çalışmada ": "Die Studie ergab, ",
  "zamanında verilen geri bildirimin, öz düzenleme ile başarı arasındaki ilişkide kısmi aracı rol üstlendiği": "dass zeitnahes Feedback den Zusammenhang zwischen Selbstregulation und Leistung teilweise vermittelte",
