  "örnek kaynak": "Beispielquelle",
  "Örnek çalışma · 2.3 Kuramsal çerçeve": "Beispielarbeit · 2.3 Theoretischer Rahmen",
  "Örnek gösterimdir; kaynaklar ve pasajlar temsilidir. Kendi çalışmanızda pasajlar, eklediğiniz kaynakların kendi metninden gelir. Bir atıfın veya kaynağın üzerine gelerek doğrulamayı görün.": "Beispieldarstellung; Quellen und Passagen sind repräsentativ. In Ihrer eigenen Arbeit stammen die Passagen aus dem tatsächlichen Text der von Ihnen hinzugefügten Quellen. Fahren Sie mit der Maus über ein Zitat oder eine Quelle, um die Verifizierung zu sehen.",
  "“{title}” çalışması; tüm bölümleri, kaynakları, sohbetleri ve sürümleriyle birlikte kalıcı olarak silinsin mi? Bu işlem geri alınamaz.": "„{title}“ samt allen Abschnitten, Quellen, Chats und Versionen endgültig löschen? Dies kann nicht rückgängig gemacht werden.",
