  "“{name}” dosyası kalıcı olarak silinsin mi? Dosya depolamadan da kaldırılır.": "„{name}“ endgültig löschen? Die Datei wird auch aus dem Speicher entfernt.",
  "“{title}” kaynağı kalıcı olarak silinsin mi? Metinde bu kaynağa verilen atıflar kaynaksız kalır.": "Die Quelle „{title}“ endgültig löschen? Zitate darauf in Ihrem Text bleiben dann ohne Quelle.",
  "Silinemedi": "Löschen fehlgeschlagen",
  "“{title}” anketi ve tüm cevapları kalıcı olarak silinsin mi? Bu işlem geri alınamaz.": "Die Umfrage „{title}“ samt allen Antworten endgültig löschen? Dies kann nicht rückgängig gemacht werden.",
  "Bu kayıt kalıcı olarak silinsin mi? Bu işlem geri alınamaz.": "Diesen Eintrag endgültig löschen? Dies kann nicht rückgängig gemacht werden.",
  "Silindi": "Gelöscht",
  "Sohbeti sil": "Chat löschen",
  "Bu bölümdeki asistan sohbeti ve tüm mesajları kalıcı olarak silinsin mi? Metninize eklediğiniz yazılar etkilenmez.": "Den Assistenten-Chat dieses Abschnitts samt allen Nachrichten endgültig löschen? Text, den Sie in Ihr Dokument übernommen haben, bleibt unberührt.",
