  "Maddeler özgün taslaktır; geçerlik-güvenirlik çalışması yapılmamıştır. Yerleşik bir ölçek kullanacaksanız izinli uyarlamasını ekleyin.": "Die Items sind ursprüngliche Entwürfe ohne Validitäts- oder Reliabilitätsprüfung. Wenn Sie eine etablierte Skala verwenden möchten, fügen Sie deren lizenzierte Adaptation hinzu.",
