  "İnceleme:": "Prüfung:",
  "Aşağıdaki düğmelerle soru ekleyin. Hazır bir ölçek kullanacaksanız maddelerini “Likert ölçeği” ile tek seferde yapıştırabilirsiniz. İpucu: Likert ölçeği ekleyip yalnızca ölçmek istediğiniz kavramı yazın, ✨ düğmesiyle maddeleri yapay zekâ önersin.": "Fügen Sie mit den Schaltflächen unten Fragen hinzu. Um eine vorhandene Skala zu verwenden, fügen Sie ihre Items mit „Likert-Skala“ auf einmal ein. Tipp: Fügen Sie eine Likert-Skala hinzu, schreiben Sie nur das zu messende Konstrukt hinein und lassen Sie sich mit der Schaltfläche ✨ Items von der KI vorschlagen.",
  "Likert ölçeğinde yönergeyi veya ölçmek istediğiniz kavramı yazmanız yeterli; maddeleri yapay zekâ önerir.": "Schreiben Sie bei einer Likert-Skala nur die Anweisung oder das zu messende Konstrukt; die KI schlägt die Items vor.",
