  "Bilgilendirilmiş onam metni yok. Etik kurullar çoğunlukla ister (Ayarlar sekmesi).": "Es gibt keine Einwilligungserklärung. Ethikkommissionen verlangen in der Regel eine (Tab „Einstellungen“).",
  "Onam metninde doldurulmamış alanlar var (köşeli parantez içindekiler).": "Die Einwilligungserklärung enthält nicht ausgefüllte Felder (die in eckigen Klammern).",
  "Demografik soru yok. Örneklemi betimlemek için yaş, cinsiyet gibi sorular eklemeyi düşünün.": "Es gibt keine demografischen Fragen. Ergänzen Sie etwa Alter und Geschlecht, um die Stichprobe zu beschreiben.",
  "Anket yaklaşık {n} dakika sürüyor. 15–20 dakikayı aşan anketlerde yarıda bırakma artar.": "Die Umfrage dauert etwa {n} Minuten. Bei Umfragen über 15–20 Minuten steigt die Abbruchquote.",
