  "{n}. sorudaki ölçekte ters madde yok. Hep aynı yönde cevaplamayı fark etmek için 1–2 ters madde eklenebilir.": "Die Skala in Frage {n} hat keine invers kodierten Items. 1–2 solcher Items helfen, gleichförmiges Antworten zu erkennen.",
  "{n}. sorudaki ölçek {k} maddeden oluşuyor; katılımcı yorulabilir, bölmeyi düşünün.": "Die Skala in Frage {n} hat {k} Items; Teilnehmende könnten ermüden – erwägen Sie eine Aufteilung.",
  "{n}. soru (sayı) için alt/üst sınır yok; hatalı girişleri önlemek için aralık belirleyin.": "Frage {n} (Zahl) hat kein Min./Max.; legen Sie einen Bereich fest, um ungültige Eingaben zu vermeiden.",
  "{n}. soruda (çoklu seçim) “Diğer” seçeneği yok.": "Frage {n} (Mehrfachauswahl) hat keine Option „Sonstiges“.",
  "{n}. soruda {k} seçenek var; uzun listeler okunmayabilir.": "Frage {n} hat {k} Antwortoptionen; lange Listen werden womöglich nicht gelesen.",
