  "Kurgu bir plandır: kaynak, bulgu veya istatistik içermez. Önerilen örneklem ve analizleri danışmanınızla birlikte kesinleştirin.": "Das Konzept ist ein Plan: Es enthält keine Quellen, Ergebnisse oder Statistiken. Legen Sie die vorgeschlagene Stichprobe und die Analysen mit Ihrer Betreuung fest.",
