  "Kurgu, yazdığınız girişe göre yeniden oluşturulacak. Mevcut taslaktaki değişiklikler değişebilir. Devam edilsin mi?": "Das Konzept wird aus Ihren Angaben neu erstellt. Änderungen im aktuellen Entwurf können dabei ersetzt werden. Fortfahren?",
  "Kurgu; araştırma probleminizi, amacınızı, sorularınızı, yöntemi ve her bölümde ne yazılacağını tek ekranda gösterir. İstediğiniz yeri değiştirebilirsiniz. Onayladığınızda çalışma bu plana göre adım adım ilerler.": "Das Konzept zeigt Forschungsproblem, Ziel, Fragen, Methode und den Inhalt jedes Abschnitts auf einen Blick. Ändern Sie, was Sie möchten. Sobald Sie es bestätigen, geht Ihre Arbeit Schritt für Schritt nach diesem Plan voran.",
