  "Yeni öneri yazıldı.": "Neuer Vorschlag hinzugefügt.",
  "Yeniden öner": "Erneut vorschlagen",
  "Yöntem tercihiniz, örnekleminiz, danışmanınızın önerileri veya kısıtlarınız varsa yazın; kurgu buna göre kurulur. Boş bırakırsanız çalışma bilgilerinizden kurgulanır.": "Nennen Sie Ihre bevorzugte Methode, die Stichprobe, Vorschläge Ihrer Betreuung oder Einschränkungen; das Konzept wird darauf aufgebaut. Bleibt das Feld leer, wird es aus den Angaben zu Ihrer Arbeit erstellt.",
  "Çalışmanın kurgusu": "Konzept der Studie",
  "Çalışmanız bu plana göre adım adım ilerleyecek. Kurguyu istediğiniz zaman sol menüden açıp değiştirebilirsiniz.": "Ihre Arbeit geht Schritt für Schritt nach diesem Plan voran. Sie können das Konzept jederzeit über das linke Menü öffnen und ändern.",
  "Çalışmanızın kurgusu hazırlanıyor…": "Ihr Studienkonzept wird vorbereitet …",
  "Öneri alınamadı": "Es konnte kein Vorschlag abgerufen werden",
  "ör. Lise öğretmenleriyle görüşme yaparak nitel bir çalışma yapmak istiyorum; özellikle uzaktan eğitimde yaşadıkları zorluklara odaklanacağım.": "z. B. Ich möchte eine qualitative Studie mit Interviews mit Lehrkräften der Oberstufe durchführen und mich auf ihre Schwierigkeiten im Fernunterricht konzentrieren.",
  "ör. Nicel değil nitel yöntem kullanmak istiyorum; örneklemi 15 öğretmenle sınırla.": "z. B. Ich möchte eine qualitative statt einer quantitativen Methode; begrenze die Stichprobe auf 15 Lehrkräfte.",
  "Şu kısımlar boş: {list}. Yine de onaylansın mı? Daha sonra da tamamlayabilirsiniz.": "Diese Teile sind leer: {list}. Trotzdem bestätigen? Sie können sie später ergänzen.",
  "Araştırma problemi": "Forschungsproblem",
  "Yöntem ve desen": "Methode und Design",
  "Katılımcılar / kapsam": "Teilnehmende / Umfang",
