  "Analiz / sentez": "Auswertung / Synthese",
  "Özgün değer ve katkı": "Originalität und Beitrag",
  "Hangi boşluğu veya sorunu ele alıyorsunuz? Neden önemli?": "Welche Lücke oder welches Problem bearbeiten Sie? Warum ist es wichtig?",
  "Çalışma sonunda neyi ortaya koymak istiyorsunuz?": "Was möchten Sie am Ende der Studie herausgefunden haben?",
  "Nicel / nitel / karma; desen (ör. ilişkisel tarama, durum çalışması, sistematik derleme)": "Quantitativ / qualitativ / gemischt; Design (z. B. korrelative Querschnittsbefragung, Fallstudie, systematisches Review)",
  "Evren ve örneklem, çalışma grubu ya da derlemeye alınacak çalışmaların ölçütleri": "Grundgesamtheit und Stichprobe, Untersuchungsgruppe oder Einschlusskriterien für die gesichteten Studien",
  "Ölçekler, görüşme formu, belge, veri tabanları ve arama stratejisi": "Skalen, Interviewleitfaden, Dokumente, Datenbanken und Suchstrategie",
