  "Alana ve uygulamaya ne katacak?": "Was trägt die Arbeit zum Fach und zur Praxis bei?",
  "Kurgu": "Konzept",
  "Planı görün, düzenleyin, onaylayın": "Plan ansehen, bearbeiten und bestätigen",
  "Kurguya uygun başlığı seçin": "Einen zum Konzept passenden Titel wählen",
