  "Öneri okunamadı, lütfen tekrar deneyin": "Der Vorschlag konnte nicht gelesen werden, bitte versuchen Sie es erneut",
  "Kurgu çok uzun; bazı alanları kısaltın": "Das Konzept ist zu lang; kürzen Sie einige Felder",
  "A4, 12 punto, 1,5 satır aralığında ortalama ~275 kelime": "Durchschnittlich etwa 275 Wörter auf A4, 12 pt, Zeilenabstand 1,5",
  "Boş bırakırsanız çalışma türünüze ve seviyenize uygun bir uzunluk önerilir. Toplam uzunluk, bölümlere akademik ağırlıklarına göre dağıtılır.": "Bleibt das Feld leer, wird eine zur Art und Stufe Ihrer Arbeit passende Länge vorgeschlagen. Die Gesamtzahl wird nach akademischem Gewicht auf die Abschnitte verteilt.",
  "Bu bölümün yaklaşık kelime sayısı": "Ungefähre Wortzahl dieses Abschnitts",
  "Bölüm kelimelerini akademik ağırlıklara göre baştan dağıt": "Wortzahlen der Abschnitte nach akademischem Gewicht neu verteilen",
  "Bölümler sabittir; her bölümde ne yazılacağını ve yaklaşık kaç kelime olacağını buradan değiştirebilirsiniz. Asistan her bölümü bu plana ve uzunluğa göre yazar.": "Die Abschnitte stehen fest; hier können Sie ändern, was jeder behandelt und wie viele Wörter er ungefähr umfasst. Der Assistent schreibt jeden Abschnitt nach diesem Plan und dieser Länge.",
  "Bölümlere dağıtılan: {a} / {t} kelime": "Den Abschnitten zugeteilt: {a} / {t} Wörter",
