  "Toplama eşitle": "An die Gesamtzahl anpassen",
  "Uzunluk: bu alt başlık yaklaşık {n} kelime olsun (bölüm hedefi ~{total} kelime, {k} alt başlığa bölünüyor).": "Länge: Diese Unterüberschrift soll etwa {n} Wörter umfassen (Ziel des Abschnitts ~{total} Wörter, verteilt auf {k} Unterüberschriften).",
