  "Hedef uzunluk (kelime / sayfa)": "Ziellänge (Wörter / Seiten)",
  "Boş bırakırsanız çalışma türünüze ve seviyenize uygun bir uzunluk önerilir. Toplam kelime, bölümlere akademik ağırlıklarına göre dağıtılır; her bölümün kelime sayısını sonra değiştirebilirsiniz.": "Bleibt das Feld leer, wird eine zur Art und Stufe Ihrer Arbeit passende Länge vorgeschlagen. Die Gesamtzahl wird nach akademischem Gewicht auf die Abschnitte verteilt; die Wortzahl jedes Abschnitts können Sie anschließend ändern.",
