  "Akademisyen grupları, araştırma ekipleri, laboratuvarlar ve bölümler için.": "Für Lehrstuhlgruppen, Forschungsteams, Labore und Fachbereiche.",
  "Basic, Pro veya Premium: seçtiğiniz paketin tüm özellikleri": "Basic, Pro oder Premium: alle Funktionen des gewählten Tarifs",
  "Ekip adına tek ödeme": "Eine Zahlung für das ganze Team",
  "Ekip teklifi al": "Teamangebot anfordern",
  "Ekip yöneticisi paneli: üyeleri görme ve yönetme": "Team-Adminbereich: Mitglieder ansehen und verwalten",
  "En az {n} kişi; kişi sayısında üst sınır yok": "Mindestens {n} Personen; keine Obergrenze für die Teamgröße",
  "Her üyeye kendi hesabı, kendi çalışmaları ve kullanım hakları": "Jedes Mitglied erhält ein eigenes Konto, eigene Arbeiten und ein eigenes Nutzungskontingent",
  "Merhaba, Academiana Akademik Ekip paketi (%{p} indirim) için teklif almak istiyorum.\nKurum / bölüm / ekip adı: \nKişi sayısı: \nİlgilendiğimiz paket (Basic / Pro / Premium): ": "Hallo, ich hätte gern ein Angebot für den Academiana-Tarif „Akademisches Team“ ({p} % Rabatt).\nInstitution / Fachbereich / Team: \nAnzahl der Personen: \nGewünschter Tarif (Basic / Pro / Premium): ",
