  "Academiana ile neler elde edeceğinizi görün: kurgudan kaynakçaya, istatistik tablosundan savunma provasına kadar her hizmetin örneği.": "Sehen Sie, was Sie mit Academiana bekommen: ein Beispiel für jede Leistung, vom Studienkonzept bis zum Literaturverzeichnis, von Statistiktabellen bis zur Probe der Verteidigung.",
