  "Kaynağı olmayan iddia uydurulmaz: sistem “[KAYNAK GEREKLİ]” diye işaretler ve bu konu için kaynak aramayı önerir.": "Unbelegte Aussagen werden nie erfunden: Das System markiert sie mit „[CITATION NEEDED]“ und bietet an, zu diesem Punkt nach Quellen zu suchen.",
  "OpenAlex · Crossref · PubMed · DergiPark · TR Dizin…": "OpenAlex · Crossref · PubMed · DergiPark · TR Dizin …",
