  "Temel bulgular": "Zentrale Ergebnisse",
  "Tüm örnekler aynı kurgusal çalışma üzerindendir: “{title}”. Kaynaklar, yazarlar ve veriler temsilidir. İstatistik tabloları, grafik ve atıf biçimleri elle yazılmamıştır; sistemin kendi araçlarıyla bu örnek veriden üretilmiştir. Kendi çalışmanızda içerik, sizin kaynaklarınızdan ve verinizden gelir.": "Alle Beispiele stammen aus derselben fiktiven Studie: „{title}“. Quellen, Autor:innen und Daten dienen der Veranschaulichung. Statistiktabellen, Diagramm und Zitatformate wurden nicht von Hand geschrieben, sondern von den Werkzeugen des Systems aus diesen Beispieldaten erzeugt. In Ihrer eigenen Arbeit stammen die Inhalte aus Ihren Quellen und Ihren Daten.",
