  "Bu şifre çok zayıf; daha uzun ve tahmini zor bir şifre seçin.": "Dieses Passwort ist zu schwach; wählen Sie ein längeres, schwerer zu erratendes.",
  "E-posta birkaç dakika içinde gelmezse gereksiz (spam) klasörünü kontrol edin. Google ile kayıt olduysanız şifreye gerek yoktur; giriş ekranında “Google ile devam et”i kullanın.": "Wenn die E-Mail nicht innerhalb weniger Minuten ankommt, prüfen Sie Ihren Spam-Ordner. Wenn Sie sich mit Google registriert haben, brauchen Sie kein Passwort; nutzen Sie auf der Anmeldeseite „Mit Google fortfahren“.",
  "En az 8 karakter. Harf, rakam ve işaret karışık olursa daha güvenli olur.": "Mindestens 8 Zeichen. Eine Mischung aus Buchstaben, Ziffern und Sonderzeichen macht es sicherer.",
  "Farklı bir e-posta dene": "Andere E-Mail-Adresse versuchen",
