  "Hesabınızın e-posta adresini yazın; şifrenizi yenilemeniz için bir bağlantı gönderelim.": "Geben Sie die E-Mail-Adresse Ihres Kontos ein, und wir senden Ihnen einen Link zum Zurücksetzen Ihres Passworts.",
  "Hesap: {email}": "Konto: {email}",
  "Kısa sürede çok fazla istek yapıldı. Lütfen birkaç dakika sonra tekrar deneyin.": "Zu viele Anfragen in kurzer Zeit. Bitte versuchen Sie es in einigen Minuten erneut.",
