  "Kaynakları kontrol et": "Quellen prüfen",
  "Kaynakça dili": "Sprache des Literaturverzeichnisses",
  "Kaynakçanızı yapıştırın (her kaynak ayrı satırda). Zotero, Mendeley veya EndNote’tan alınan BibTeX/RIS da olur.": "Fügen Sie Ihr Literaturverzeichnis ein (eine Quelle pro Zeile). BibTeX/RIS aus Zotero, Mendeley oder EndNote funktioniert ebenfalls.",
  "Kaynakçanızı yapıştırın; her kaynak ayrı satırda olsun. En fazla 30 kaynak.": "Fügen Sie Ihr Literaturverzeichnis ein, eine Quelle pro Zeile. Bis zu 30 Quellen.",
