  "Kontrol ediliyor…": "Wird geprüft …",
  "Künyede fark var": "Angaben weichen ab",
  "Künyeler Crossref, DataCite ve OpenAlex kayıtlarından alınır; yapay zekâ kullanılmaz.": "Die Angaben stammen aus Datensätzen von Crossref, DataCite und OpenAlex; es wird keine KI verwendet.",
  "Madde": "Item",
  "Madde silinirse α": "α bei Weglassen des Items",
  "Madde-toplam korelasyonu .30’un altında olan veya silindiğinde alfayı yükselten maddeler vurgulanmıştır; çıkarma kararını kuramsal gerekçeyle verin.": "Items mit einer Item-Total-Korrelation unter .30 oder solche, deren Weglassen Alpha erhöht, werden hervorgehoben; stützen Sie ein Entfernen auf theoretische Gründe.",
  "Metin içi:": "Im Text:",
  "Ortalama tahmini için %{c} güven düzeyi, σ = {sd} ve ±{e} hata payıyla gereken örneklem büyüklüğü {n} olarak hesaplanmıştır (Cochran, 1977).": "Für die Schätzung eines Mittelwerts bei einem Konfidenzniveau von {c} %, σ = {sd} und einer Fehlermarge von ±{e} wurde die erforderliche Stichprobengröße mit {n} berechnet (Cochran, 1977).",
