  "Verileriniz bilgisayarınızdan çıkmaz; hesaplama tarayıcınızda yapılır.": "Ihre Daten verlassen Ihren Computer nie; die Berechnung läuft in Ihrem Browser.",
  "Yalnızca okunamayan satırlar için küçük bir yapay zekâ modeli kullanılır": "Ein kleines KI-Modell wird nur für Zeilen verwendet, die nicht gelesen werden können",
  "Yamane formülü için evren büyüklüğü gerekli.": "Die Formel von Yamane benötigt die Größe der Grundgesamtheit.",
  "Yanıt oranı %{r} ise yaklaşık {k} kişiye ulaşmanız gerekir.": "Bei einer Rücklaufquote von {r} % müssen Sie etwa {k} Personen erreichen.",
  "Yapay zekâ kullanılmaz": "Es wird keine KI verwendet",
  "Yazarlar": "Autor:innen",
  "Yazdır / PDF": "Drucken / PDF",
  "Yukarıdan bir soru türü seçerek başlayın.": "Wählen Sie oben zunächst einen Fragetyp.",
  "Yönerge (ör. Aşağıdaki ifadelere ne ölçüde katılıyorsunuz?)": "Anweisung (z. B. Inwieweit stimmen Sie den folgenden Aussagen zu?)",
  "Yöntem bölümü için örnek cümle": "Beispielsatz für Ihren Methodenteil",
