  "{a}/{b} kaynak resmî kayıttan tamamlandı; diğerleri yazdığınız metinden ayrıştırıldı, kontrol edin.": "{a}/{b} Quellen wurden aus offiziellen Datensätzen ergänzt; die übrigen wurden aus Ihrem Text ausgelesen, bitte prüfen Sie sie.",
