  "Paket ölçüleri nasıl belirlendi?": "Wie wurden die Tarifumfänge festgelegt?",
  "Aylık sayfa miktarları, 44 gerçek akademik tam metin üzerinde ölçülen ortalama sayfa uzunluğu ve bir sayfanın ortalama yapay zekâ maliyeti esas alınarak belirlenir ve paketinizin gerçek sınırıdır: yapay zekânın yazdığı taslak kelimeleri sayılır (1 sayfa = 344 kelime). Ana sayfa ve bu sayfa aynı paket kaydından beslenir.": "Die monatlichen Seitenumfänge beruhen auf der an 44 echten wissenschaftlichen Volltexten gemessenen durchschnittlichen Seitenlänge und den durchschnittlichen KI-Kosten pro Seite und sind die tatsächliche Grenze Ihres Tarifs: Gezählt werden die Wörter der von der KI geschriebenen Entwürfe (1 Seite = 344 Wörter). Startseite und diese Seite speisen sich aus demselben Tarifdatensatz.",
