  "Academiana’da ara": "In Academiana suchen",
  "13 veri tabanında eşzamanlı arama; en fazla 50 sonuç derlemeye eklenir. Arama ifadesi yöntem bölümü için kaydedilir.": "Durchsucht 13 Datenbanken gleichzeitig; bis zu 50 Ergebnisse werden dem Review hinzugefügt. Der Suchstring wird für den Methodenteil gespeichert.",
  "Ör. gamification AND mathematics achievement": "Z. B. gamification AND mathematics achievement",
  "{n} sonuç bulundu": "{n} Ergebnisse gefunden",
