  "Scopus, Web of Science, PubMed, ERIC veya ULAKBİM’den sonuçları RIS ya da BibTeX olarak dışa aktarıp yükleyin. Yinelenenler otomatik ayrılır.": "Exportieren Sie Ergebnisse aus Scopus, Web of Science, PubMed, ERIC oder ULAKBİM als RIS oder BibTeX und laden Sie sie hoch. Dubletten werden automatisch abgetrennt.",
