  "Tez, makale, derleme, araştırma önerisi, TÜBİTAK/BAP dahil 9 çalışma türü; her aşamanın kuralları, soruları ve asistanı ayrı.": "9 Arten von Arbeiten, darunter Abschlussarbeit, Artikel, Review, Forschungsexposé und TÜBİTAK/BAP; jede Phase hat eigene Regeln, Fragen und einen eigenen Assistenten.",
