  "Problem, amaç, araştırma soruları, yöntem ve bölüm bazında hedef uzunluk; asistan bütün bölümleri bu kurguya göre yazar.": "Problem, Ziel, Forschungsfragen, Methode und Ziellänge je Abschnitt; der Assistent schreibt jeden Abschnitt nach diesem Konzept.",
