  "Kaynak ve literatür": "Quellen und Literatur",
  "16 akademik veri tabanında 250 milyondan fazla yayın; her kaynağın ne kadarının okunduğu açıkça yazar.": "Über 250 Millionen Publikationen in 16 wissenschaftlichen Datenbanken; für jede Quelle sehen Sie, wie viel davon gelesen wurde.",
