  "OpenAlex, Crossref, PubMed, arXiv, ERIC, DOAJ, HAL, PLOS ve diğerleri; sonuçlar birleştirilir, tekrarlar ayıklanır.": "OpenAlex, Crossref, PubMed, arXiv, ERIC, DOAJ, HAL, PLOS und weitere; die Ergebnisse werden zusammengeführt und Dubletten entfernt.",
  "Türkiye kaynakları": "Türkische Quellen",
  "DergiPark dergileri dahil Türkçe ve Türkiye adresli yayınlar; TR Dizin ve YÖK Tez Merkezi’nde tek tıkla arama.": "Türkischsprachige und Türkei-bezogene Publikationen einschließlich DergiPark-Zeitschriften; Suche in TR Dizin und im YÖK-Thesenzentrum mit einem Klick.",
  "Tam metin okuma": "Volltextlektüre",
  "Açık erişimli metinler otomatik okunur, PDF’iniz yüklenebilir; bölümler tanınır, alıntılar yayındaki sayfa numarasıyla gelir.": "Open-Access-Texte werden automatisch gelesen, und Sie können Ihr PDF hochladen; Abschnitte werden erkannt, und Zitate erhalten die veröffentlichte Seitenzahl.",
  "Bir makaleye soru sorun; cevap yalnızca o makaleden, sayfa numaralarıyla gelir.": "Stellen Sie einem Artikel eine Frage; die Antwort stammt nur aus diesem Artikel, mit Seitenzahlen.",
  "2–8 makaleyi karşılaştırın: uyuşan noktalar, çelişen bulgular ve araştırma boşlukları tek tabloda.": "Vergleichen Sie 2–8 Artikel: Übereinstimmungen, widersprüchliche Befunde und Forschungslücken in einer Tabelle.",
  "Literatür haritası ve matrisi": "Literaturkarte und -matrix",
  "Kaynaklarınızın atıf ağı, eksik olabilecek temel çalışmalar ve amaç–yöntem–bulgu matrisi.": "Das Zitationsnetz Ihrer Quellen, möglicherweise fehlende Schlüsselwerke und eine Matrix aus Ziel, Methode und Ergebnissen.",
  "Konu bulma ve kütüphane aktarımı": "Themenfinder und Bibliotheksimport",
