  "Atıf ve doğruluk": "Zitate und Genauigkeit",
  "Bir kaynağın var olması, cümlenizi desteklediği anlamına gelmez. Academiana ikisini de denetler.": "Dass eine Quelle existiert, heißt nicht, dass sie Ihren Satz stützt. Academiana prüft beides.",
  "Canlı atıflar, 10 atıf stili": "Lebendige Zitate, 10 Zitierstile",
  "APA 7, ISNAD 2, MLA, Chicago, IEEE ve diğerleri; stil değiştiğinde metin ve kaynakça birlikte dönüşür.": "APA 7, ISNAD 2, MLA, Chicago, IEEE und weitere; wenn Sie den Stil ändern, ändern sich Text und Literaturverzeichnis gemeinsam.",
  "Atıflı her cümle kaynağın metniyle karşılaştırılır: destekliyor, kısmen, desteklemiyor veya çelişiyor; birebir alıntı ve sayfa.": "Jeder zitierte Satz wird mit dem Quellentext verglichen: stützt, teilweise, stützt nicht oder widerspricht; mit wörtlichem Zitat und Seite.",
  "Kaynaklar arası destek ve çelişki": "Stützung und Widerspruch über Quellen hinweg",
  "Atıfsız cümleleri destekleyen kaynaklarınızı önerir, cümlenizle çelişen bulguları alıntısıyla uyarır.": "Schlägt Ihre Quellen vor, die unzitierte Sätze stützen, und markiert Befunde, die Ihrem Satz widersprechen – mit Zitat.",
  "Kaynakçadaki her satır gerçek kayıtlarla eşleştirilir; var olmayan kaynak ve hatalı DOI bulunur.": "Jede Zeile des Literaturverzeichnisses wird mit echten Datensätzen abgeglichen; nicht existierende Quellen und falsche DOIs werden gefunden.",
