  "16 veri tabanında arama veya Scopus, Web of Science, PubMed’den RIS/BibTeX; benzer başlıklı yinelenenler de yakalanır.": "Durchsuchen Sie 16 Datenbanken oder importieren Sie RIS/BibTeX aus Scopus, Web of Science und PubMed; auch Dubletten mit ähnlichem Titel werden erkannt.",
