  "Paketleri gör": "Tarife ansehen",
  // D149: içe aktarma, kaynak tercihleri, seçim menüsü
  "Çalışmanız içe aktarıldı": "Ihre Arbeit wurde importiert",
  "{s} bölüm · {r} kaynak · {l} atıf bağlandı": "{s} Abschnitte · {r} Quellen · {l} Zitate verknüpft",
  "Mevcut çalışmamı içe aktar": "Meine bestehende Arbeit importieren",
  "Dosya yükleniyor…": "Datei wird hochgeladen…",
  "Yapay zekâ çalışmanızı analiz ediyor; bölümler, kaynaklar ve atıflar hazırlanıyor… Büyük belgelerde bir dakika sürebilir.": "Die KI analysiert Ihre Arbeit; Abschnitte, Quellen und Zitate werden vorbereitet… Bei großen Dokumenten kann das eine Minute dauern.",
  "Word (.docx), PDF veya metin dosyası. Yapay zekâ türünü ve konusunu çıkarır, bölümlere ayırır, kaynakçayı ekler, atıfları bağlar ve çalışma ekranını açar. Metniniz yeniden yazılmaz.": "Word- (.docx), PDF- oder Textdatei. Die KI erkennt Art und Thema, teilt sie in Abschnitte, übernimmt das Literaturverzeichnis, verknüpft die Zitate und öffnet den Arbeitsbereich. Ihr Text wird nicht umgeschrieben.",
  "veya yeni bir çalışma başlatın": "oder eine neue Arbeit beginnen",
  "Güçlü konu tanımı": "Starke Themenbeschreibung",
  "Orta konu tanımı": "Mittlere Themenbeschreibung",
  "Zayıf konu tanımı": "Schwache Themenbeschreibung",
  "Yapay zekâ bölümleri bu bağlamla daha isabetli yazar.": "Mit diesem Kontext schreibt die KI die Abschnitte treffender.",
  "Daha isabetli üretim için şunları ekleyin: {x}": "Für treffendere Ergebnisse ergänzen Sie: {x}",
  "Atıf ve kaynak tercihlerinizi ayarlayalım": "Legen wir Ihre Zitier- und Quelleneinstellungen fest",
  "Bu tercihleri sonradan Proje ayarları’ndan değiştirebilirsiniz. Kendi kaynaklarınızı (PDF, Zotero, Mendeley, .bib/.ris) çalışma ekranındaki “İçe aktar” düğmesiyle istediğiniz an ekleyebilirsiniz.": "Sie können diese Einstellungen später in den Projekteinstellungen ändern. Eigene Quellen (PDF, Zotero, Mendeley, .bib/.ris) fügen Sie jederzeit über die Schaltfläche „Importieren“ im Arbeitsbereich hinzu.",
  "Çalışmanızı nasıl yapılandırmak istersiniz?": "Wie möchten Sie Ihre Arbeit strukturieren?",
  "Standart bölümler": "Standardabschnitte",
  "Seçtiğiniz türün akademik bölüm düzeni (ör. Giriş, Yöntem, Bulgular, Tartışma).": "Die akademische Gliederung der gewählten Art (z. B. Einleitung, Methode, Ergebnisse, Diskussion).",
  "Akıllı bölüm planı": "Intelligenter Gliederungsplan",
  "Yapay zekâ konunuza göre problem, amaç, yöntem ve bölüm planını hedef uzunluklarıyla önerir; onayladığınız plana göre yazılır.": "Die KI schlägt zu Ihrem Thema Problem, Ziel, Methode und einen Gliederungsplan mit Ziellängen vor; geschrieben wird nach dem von Ihnen bestätigten Plan.",
  "Serbest": "Frei",
  "Tek bir metin bölümüyle başlayın; alt başlıkları kendiniz ekleyin.": "Beginnen Sie mit einem einzigen Textabschnitt und fügen Sie Unterüberschriften selbst hinzu.",
  "Veri tabanı taraması": "Datenbanksuche",
  "Yazarken gerektiğinde OpenAlex, Crossref, DergiPark gibi akademik veri tabanlarında gerçek kaynak aranır.": "Beim Schreiben wird bei Bedarf in akademischen Datenbanken wie OpenAlex, Crossref und DergiPark nach echten Quellen gesucht.",
  "Her seferinde sor": "Jedes Mal fragen",
  "Kapalı": "Aus",
