  "Özel": "Benutzerdefiniert",
  "En az atıf sayısı": "Mindestanzahl an Zitationen",
  "Atıf sayısı bilinmeyen kayıtlar (ör. bazı DergiPark makaleleri) elenmez.": "Einträge mit unbekannter Zitationszahl (z. B. manche DergiPark-Artikel) werden nicht ausgeschlossen.",
  "Ön baskıları dahil et": "Preprints einbeziehen",
  "arXiv, bioRxiv, SSRN gibi hakem değerlendirmesinden geçmemiş yayınlar.": "Noch nicht begutachtete Veröffentlichungen wie arXiv, bioRxiv und SSRN.",
