  "Word (.docx), PDF veya metin. Bölümlere ayrılır, kaynakça eklenir, atıflar bağlanır.": "Word (.docx), PDF oder Text. Wird in Abschnitte geteilt, Literatur übernommen, Zitate verknüpft.",
