  "PDF dosyaları yükle": "PDF-Dateien hochladen",
  "Makale PDF’leri kaynak olarak eklenir; tam metin okunur.": "Artikel-PDFs werden als Quellen hinzugefügt; der Volltext wird gelesen.",
  "Zotero’dan içe aktar": "Aus Zotero importieren",
  "Kütüphanenizden veya bir koleksiyondan doğrudan.": "Direkt aus Ihrer Bibliothek oder einer Sammlung.",
  "Mendeley’den içe aktar": "Aus Mendeley importieren",
  "Mendeley’den dışa aktardığınız BibTeX/RIS dosyasıyla.": "Mit der aus Mendeley exportierten BibTeX-/RIS-Datei.",
  "DOI / PMID / arXiv ile ekle": "Per DOI / PMID / arXiv hinzufügen",
  "Kimliği yapıştırın; künye kayıt otoritesinden gelir.": "Kennung einfügen; die Angaben kommen von der Registrierungsstelle.",
  ".bib / .ris içe aktar": ".bib / .ris importieren",
  "EndNote, JabRef ve diğer programların dosyaları.": "Dateien aus EndNote, JabRef und anderen Programmen.",
  "Yazdığınız çalışmayı yükleyin. Metniniz yeniden yazılmaz: en üst düzey başlıklarınız bölüm olur, boş bölümlere yerleşir; dolu bölümlerin üzerine yazılmaz. Kaynakça doğrulanıp eklenir, metin içi atıflar bağlanır.": "Laden Sie Ihre geschriebene Arbeit hoch. Ihr Text wird nicht umgeschrieben: Ihre obersten Überschriften werden zu Abschnitten und füllen leere Abschnitte; Abschnitte mit Text werden nie überschrieben. Das Literaturverzeichnis wird geprüft und übernommen, Zitate im Text werden verknüpft.",
  "En iyi sonuç Word (.docx) ile alınır; PDF’te başlıklar ve paragraflar yaklaşık olarak çıkarılır.": "Word (.docx) liefert das beste Ergebnis; in PDFs werden Überschriften und Absätze nur näherungsweise erkannt.",
  "Dosya seç": "Datei wählen",
  "Bilgisayarınızdan en fazla 10 makale PDF’i seçin. Künye DOI ile doğrulanır, tam metin okunur ve “Kaynağa sor” ile kullanılabilir.": "Wählen Sie bis zu 10 Artikel-PDFs von Ihrem Computer. Die Angaben werden per DOI geprüft, der Volltext wird gelesen und ist mit „Quelle fragen“ nutzbar.",
  "PDF seç": "PDFs wählen",
  "zotero.org → Settings → Security (Feeds/API) sayfasını açın.": "Öffnen Sie zotero.org → Settings → Security (Feeds/API).",
  "“Your user ID for use in API calls” numarasını kopyalayın.": "Kopieren Sie die Nummer „Your user ID for use in API calls“.",
  "“Create new private key” ile yalnızca okuma izinli bir anahtar oluşturun.": "Erstellen Sie mit „Create new private key“ einen Schlüssel nur mit Leserechten.",
