  "Anahtarınız saklanmaz; yalnızca bu aktarım için kullanılır. En fazla 300 kayıt aktarılır, ekler ve notlar alınmaz.": "Ihr Schlüssel wird nicht gespeichert, sondern nur für diesen Import verwendet. Es werden bis zu 300 Einträge übernommen, Anhänge und Notizen nicht.",
  "Zotero’dan aktar": "Aus Zotero übernehmen",
  "Mendeley Reference Manager’da aktarmak istediğiniz kaynakları seçin (tümü için Ctrl/Cmd+A).": "Wählen Sie im Mendeley Reference Manager die gewünschten Quellen aus (Strg/Cmd+A für alle).",
  "Sağ tık → “Export” (Dışa aktar) → BibTeX (.bib) veya RIS (.ris) seçip kaydedin.": "Rechtsklick → „Export“ → BibTeX (.bib) oder RIS (.ris) wählen und speichern.",
  "Kaydettiğiniz dosyayı aşağıdan yükleyin.": "Laden Sie die gespeicherte Datei unten hoch.",
  "Mendeley, üçüncü taraf uygulamalara doğrudan bağlantıyı kısıtladığı için aktarım dosya ile yapılır.": "Da Mendeley direkte Verbindungen von Drittanbieter-Apps einschränkt, erfolgt der Import über eine Datei.",
  "BibTeX (.bib), RIS (.ris) veya CSL-JSON (.json) dosyası yükleyin. Kaynaklar DOI ile doğrulanır; projede olanlar atlanır.": "Laden Sie eine BibTeX- (.bib), RIS- (.ris) oder CSL-JSON-Datei (.json) hoch. Quellen werden per DOI geprüft; bereits vorhandene werden übersprungen.",
